const e={BSB:{name:"Berean Study Bible",license:"Berean Study Bible text (2016/2020 edition, bundled via @bible-help/get-bible-verses), released by Bible Hub under free licensing; its successor, the Berean Standard Bible, was dedicated to the public domain in 2023.",url:"https://berean.bible/"},KJV:{name:"King James Version (1769)",license:"Public domain (outside the UK).",url:"https://www.kingjamesbibleonline.org/"},WEB:{name:"World English Bible",license:"Public domain.",url:"https://worldenglish.bible/"}},t=JSON.parse(`{"revelation-20":{"BSB":[{"ref":"Revelation 20:1","text":"Then I saw an angel coming down from heaven with the key to the Abyss, holding in his hand a great chain."},{"ref":"Revelation 20:2","text":"He seized the dragon, that ancient serpent who is the devil and Satan, and bound him for a thousand years."},{"ref":"Revelation 20:3","text":"And he threw him into the Abyss, shut it, and sealed it over him, so that he could not deceive the nations until the thousand years were complete. After that, he must be released for a brief period of time."},{"ref":"Revelation 20:4","text":"Then I saw the thrones, and those seated on them had been given authority to judge. And I saw the souls of those who had been beheaded for their testimony of Jesus and for the word of God, and those who had not worshiped the beast or its image, and had not received its mark on their foreheads or hands. And they came to life and reigned with Christ for a thousand years."},{"ref":"Revelation 20:5","text":"The rest of the dead did not come back to life until the thousand years were complete. This is the first resurrection."},{"ref":"Revelation 20:6","text":"Blessed and holy are those who share in the first resurrection! The second death has no power over them, but they will be priests of God and of Christ, and will reign with Him for a thousand years."},{"ref":"Revelation 20:7","text":"When the thousand years are complete, Satan will be released from his prison,"},{"ref":"Revelation 20:8","text":"and will go out to deceive the nations in the four corners of the earth—Gog and Magog—to assemble them for battle. Their number is like the sand of the seashore."},{"ref":"Revelation 20:9","text":"And they marched across the broad expanse of the earth and surrounded the camp of the saints and the beloved city. But fire came down from heaven and consumed them."},{"ref":"Revelation 20:10","text":"And the devil who had deceived them was thrown into the lake of fire and sulfur, into which the beast and the false prophet had already been thrown. There they will be tormented day and night forever and ever."}],"KJV":[{"ref":"Revelation 20:1","text":"And I saw an angel come down from heaven, having the key of the bottomless pit and a great chain in his hand."},{"ref":"Revelation 20:2","text":"And he laid hold on the dragon, that old serpent, which is the Devil, and Satan, and bound him a thousand years,"},{"ref":"Revelation 20:3","text":"And cast him into the bottomless pit, and shut him up, and set a seal upon him, that he should deceive the nations no more, till the thousand years should be fulfilled: and after that he must be loosed a little season."},{"ref":"Revelation 20:4","text":"And I saw thrones, and they sat upon them, and judgment was given unto them: and I saw the souls of them that were beheaded for the witness of Jesus, and for the word of God, and which had not worshipped the beast, neither his image, neither had received his mark upon their foreheads, or in their hands; and they lived and reigned with Christ a thousand years."},{"ref":"Revelation 20:5","text":"But the rest of the dead lived not again until the thousand years were finished. This is the first resurrection."},{"ref":"Revelation 20:6","text":"Blessed and holy is he that hath part in the first resurrection: on such the second death hath no power, but they shall be priests of God and of Christ, and shall reign with him a thousand years."},{"ref":"Revelation 20:7","text":"And when the thousand years are expired, Satan shall be loosed out of his prison,"},{"ref":"Revelation 20:8","text":"And shall go out to deceive the nations which are in the four quarters of the earth, Gog and Magog, to gather them together to battle: the number of whom is as the sand of the sea."},{"ref":"Revelation 20:9","text":"And they went up on the breadth of the earth, and compassed the camp of the saints about, and the beloved city: and fire came down from God out of heaven, and devoured them."},{"ref":"Revelation 20:10","text":"And the devil that deceived them was cast into the lake of fire and brimstone, where the beast and the false prophet are, and shall be tormented day and night for ever and ever."}],"WEB":[{"ref":"Revelation 20:1","text":"I saw an angel coming down out of heaven, having the key of the abyss and a great chain in his hand."},{"ref":"Revelation 20:2","text":"He seized the dragon, the old serpent, which is the devil and Satan, who deceives the whole inhabited earth, and bound him for a thousand years,"},{"ref":"Revelation 20:3","text":"and cast him into the abyss, and shut it, and sealed it over him, that he should deceive the nations no more, until the thousand years were finished. After this, he must be freed for a short time."},{"ref":"Revelation 20:4","text":"I saw thrones, and they sat on them, and judgment was given to them. I saw the souls of those who had been beheaded for the testimony of Jesus, and for the word of God, and such as didn’t worship the beast nor his image, and didn’t receive the mark on their forehead and on their hand. They lived and reigned with Christ for a thousand years."},{"ref":"Revelation 20:5","text":"The rest of the dead didn’t live until the thousand years were finished. This is the first resurrection."},{"ref":"Revelation 20:6","text":"Blessed and holy is he who has part in the first resurrection. Over these, the second death has no power, but they will be priests of God and of Christ, and will reign with him one thousand years."},{"ref":"Revelation 20:7","text":"And after the thousand years, Satan will be released from his prison,"},{"ref":"Revelation 20:8","text":"and he will come out to deceive the nations which are in the four corners of the earth, Gog and Magog, to gather them together to the war; the number of whom is as the sand of the sea."},{"ref":"Revelation 20:9","text":"They went up over the width of the earth, and surrounded the camp of the saints, and the beloved city. Fire came down out of heaven from God and devoured them."},{"ref":"Revelation 20:10","text":"The devil who deceived them was thrown into the lake of fire and sulfur, where the beast and the false prophet are also. They will be tormented day and night forever and ever."}]},"matthew-24":{"BSB":[{"ref":"Matthew 24:1","text":"As Jesus left the temple and was walking away, His disciples came up to Him to point out its buildings."},{"ref":"Matthew 24:2","text":"“Do you see all these things?” He replied. “Truly I tell you, not one stone here will be left on another; every one will be thrown down.”"},{"ref":"Matthew 24:3","text":"While Jesus was sitting on the Mount of Olives, the disciples came to Him privately. “Tell us,” they said, “when will these things happen, and what will be the sign of Your coming and of the end of the age?”"},{"ref":"Matthew 24:4","text":"Jesus answered, “See to it that no one deceives you."},{"ref":"Matthew 24:5","text":"For many will come in My name, claiming, ‘I am the Christ,’ and will deceive many."},{"ref":"Matthew 24:6","text":"You will hear of wars and rumors of wars, but see to it that you are not alarmed. These things must happen, but the end is still to come."},{"ref":"Matthew 24:7","text":"Nation will rise against nation, and kingdom against kingdom. There will be famines and earthquakes in various places."},{"ref":"Matthew 24:8","text":"All these are the beginning of birth pains."},{"ref":"Matthew 24:9","text":"Then they will deliver you over to be persecuted and killed, and you will be hated by all nations because of My name."},{"ref":"Matthew 24:10","text":"At that time many will fall away and will betray and hate one another,"},{"ref":"Matthew 24:11","text":"and many false prophets will arise and mislead many."},{"ref":"Matthew 24:12","text":"Because of the multiplication of wickedness, the love of most will grow cold."},{"ref":"Matthew 24:13","text":"But the one who perseveres to the end will be saved."},{"ref":"Matthew 24:14","text":"And this gospel of the kingdom will be preached in all the world as a testimony to all nations, and then the end will come."},{"ref":"Matthew 24:15","text":"So when you see standing in the holy place ‘the abomination of desolation,’ described by the prophet Daniel (let the reader understand),"},{"ref":"Matthew 24:16","text":"then let those who are in Judea flee to the mountains."},{"ref":"Matthew 24:17","text":"Let no one on the housetop come down to retrieve anything from his house."},{"ref":"Matthew 24:18","text":"And let no one in the field return for his cloak."},{"ref":"Matthew 24:19","text":"How miserable those days will be for pregnant and nursing mothers!"},{"ref":"Matthew 24:20","text":"Pray that your flight will not occur in the winter or on the Sabbath."},{"ref":"Matthew 24:21","text":"For at that time there will be great tribulation, unmatched from the beginning of the world until now, and never to be seen again."},{"ref":"Matthew 24:22","text":"If those days had not been cut short, nobody would be saved. But for the sake of the elect, those days will be cut short."},{"ref":"Matthew 24:23","text":"At that time, if anyone says to you, ‘Look, here is the Christ!’ or ‘There He is!’ do not believe it."},{"ref":"Matthew 24:24","text":"For false Christs and false prophets will appear and perform great signs and wonders that would deceive even the elect, if that were possible."},{"ref":"Matthew 24:25","text":"See, I have told you in advance."},{"ref":"Matthew 24:26","text":"So if they tell you, ‘There He is in the wilderness,’ do not go out; or, ‘Here He is in the inner rooms,’ do not believe it."},{"ref":"Matthew 24:27","text":"For just as the lightning comes from the east and flashes as far as the west, so will be the coming of the Son of Man."},{"ref":"Matthew 24:28","text":"Wherever there is a carcass, there the vultures will gather."},{"ref":"Matthew 24:29","text":"Immediately after the tribulation of those days: ‘The sun will be darkened, and the moon will not give its light; the stars will fall from the sky, and the powers of the heavens will be shaken.’"},{"ref":"Matthew 24:30","text":"At that time the sign of the Son of Man will appear in heaven, and all the tribes of the earth will mourn. They will see the Son of Man coming on the clouds of heaven, with power and great glory."},{"ref":"Matthew 24:31","text":"And He will send out His angels with a loud trumpet call, and they will gather His elect from the four winds, from one end of the heavens to the other."},{"ref":"Matthew 24:32","text":"Now learn this lesson from the fig tree: As soon as its branches become tender and sprout leaves, you know that summer is near."},{"ref":"Matthew 24:33","text":"So also, when you see all these things, you will know that He is near, right at the door."},{"ref":"Matthew 24:34","text":"Truly I tell you, this generation will not pass away until all these things have happened."},{"ref":"Matthew 24:35","text":"Heaven and earth will pass away, but My words will never pass away."},{"ref":"Matthew 24:36","text":"No one knows about that day or hour, not even the angels in heaven, nor the Son, but only the Father."},{"ref":"Matthew 24:37","text":"As it was in the days of Noah, so will it be at the coming of the Son of Man."},{"ref":"Matthew 24:38","text":"For in the days before the flood, people were eating and drinking, marrying and giving in marriage, up to the day Noah entered the ark."},{"ref":"Matthew 24:39","text":"And they were oblivious, until the flood came and swept them all away. So will it be at the coming of the Son of Man."},{"ref":"Matthew 24:40","text":"Two men will be in the field: one will be taken and the other left."},{"ref":"Matthew 24:41","text":"Two women will be grinding at the mill: one will be taken and the other left."},{"ref":"Matthew 24:42","text":"Therefore keep watch, because you do not know the day on which your Lord will come."},{"ref":"Matthew 24:43","text":"But understand this: If the homeowner had known in which watch of the night the thief was coming, he would have kept watch and would not have let his house be broken into."},{"ref":"Matthew 24:44","text":"For this reason, you also must be ready, because the Son of Man will come at an hour you do not expect."},{"ref":"Matthew 24:45","text":"Who then is the faithful and wise servant, whom the master has put in charge of his household, to give the others their food at the proper time?"},{"ref":"Matthew 24:46","text":"Blessed is that servant whose master finds him doing so when he returns."},{"ref":"Matthew 24:47","text":"Truly I tell you, he will put him in charge of all his possessions."},{"ref":"Matthew 24:48","text":"But suppose that servant is wicked and says in his heart, ‘My master will be away a long time.’"},{"ref":"Matthew 24:49","text":"And he begins to beat his fellow servants and to eat and drink with drunkards."},{"ref":"Matthew 24:50","text":"The master of that servant will come on a day he does not expect and at an hour he does not anticipate."},{"ref":"Matthew 24:51","text":"Then he will cut him to pieces and assign him a place with the hypocrites, where there will be weeping and gnashing of teeth."}],"KJV":[{"ref":"Matthew 24:1","text":"And Jesus went out, and departed from the temple: and his disciples came to him for to shew him the buildings of the temple."},{"ref":"Matthew 24:2","text":"And Jesus said unto them, See ye not all these things? verily I say unto you, There shall not be left here one stone upon another, that shall not be thrown down."},{"ref":"Matthew 24:3","text":"# And as he sat upon the mount of Olives, the disciples came unto him privately, saying, Tell us, when shall these things be? and what shall be the sign of thy coming, and of the end of the world?"},{"ref":"Matthew 24:4","text":"And Jesus answered and said unto them, Take heed that no man deceive you."},{"ref":"Matthew 24:5","text":"For many shall come in my name, saying, I am Christ; and shall deceive many."},{"ref":"Matthew 24:6","text":"And ye shall hear of wars and rumours of wars: see that ye be not troubled: for all these things must come to pass, but the end is not yet."},{"ref":"Matthew 24:7","text":"For nation shall rise against nation, and kingdom against kingdom: and there shall be famines, and pestilences, and earthquakes, in divers places."},{"ref":"Matthew 24:8","text":"All these are the beginning of sorrows."},{"ref":"Matthew 24:9","text":"Then shall they deliver you up to be afflicted, and shall kill you: and ye shall be hated of all nations for my name's sake."},{"ref":"Matthew 24:10","text":"And then shall many be offended, and shall betray one another, and shall hate one another."},{"ref":"Matthew 24:11","text":"And many false prophets shall rise, and shall deceive many."},{"ref":"Matthew 24:12","text":"And because iniquity shall abound, the love of many shall wax cold."},{"ref":"Matthew 24:13","text":"But he that shall endure unto the end, the same shall be saved."},{"ref":"Matthew 24:14","text":"And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come."},{"ref":"Matthew 24:15","text":"When ye therefore shall see the abomination of desolation, spoken of by Daniel the prophet, stand in the holy place, (whoso readeth, let him understand:)"},{"ref":"Matthew 24:16","text":"Then let them which be in Judaea flee into the mountains:"},{"ref":"Matthew 24:17","text":"Let him which is on the housetop not come down to take any thing out of his house:"},{"ref":"Matthew 24:18","text":"Neither let him which is in the field return back to take his clothes."},{"ref":"Matthew 24:19","text":"And woe unto them that are with child, and to them that give suck in those days!"},{"ref":"Matthew 24:20","text":"But pray ye that your flight be not in the winter, neither on the sabbath day:"},{"ref":"Matthew 24:21","text":"For then shall be great tribulation, such as was not since the beginning of the world to this time, no, nor ever shall be."},{"ref":"Matthew 24:22","text":"And except those days should be shortened, there should no flesh be saved: but for the elect's sake those days shall be shortened."},{"ref":"Matthew 24:23","text":"Then if any man shall say unto you, Lo, here is Christ, or there; believe it not."},{"ref":"Matthew 24:24","text":"For there shall arise false Christs, and false prophets, and shall shew great signs and wonders; insomuch that, if it were possible, they shall deceive the very elect."},{"ref":"Matthew 24:25","text":"Behold, I have told you before."},{"ref":"Matthew 24:26","text":"Wherefore if they shall say unto you, Behold, he is in the desert; go not forth: behold, he is in the secret chambers; believe it not."},{"ref":"Matthew 24:27","text":"For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of man be."},{"ref":"Matthew 24:28","text":"For wheresoever the carcase is, there will the eagles be gathered together."},{"ref":"Matthew 24:29","text":"# Immediately after the tribulation of those days shall the sun be darkened, and the moon shall not give her light, and the stars shall fall from heaven, and the powers of the heavens shall be shaken:"},{"ref":"Matthew 24:30","text":"And then shall appear the sign of the Son of man in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of man coming in the clouds of heaven with power and great glory."},{"ref":"Matthew 24:31","text":"And he shall send his angels with a great sound of a trumpet, and they shall gather together his elect from the four winds, from one end of heaven to the other."},{"ref":"Matthew 24:32","text":"Now learn a parable of the fig tree; When his branch is yet tender, and putteth forth leaves, ye know that summer is nigh:"},{"ref":"Matthew 24:33","text":"So likewise ye, when ye shall see all these things, know that it is near, even at the doors."},{"ref":"Matthew 24:34","text":"Verily I say unto you, This generation shall not pass, till all these things be fulfilled."},{"ref":"Matthew 24:35","text":"Heaven and earth shall pass away, but my words shall not pass away."},{"ref":"Matthew 24:36","text":"# But of that day and hour knoweth no man, no, not the angels of heaven, but my Father only."},{"ref":"Matthew 24:37","text":"But as the days of Noe were, so shall also the coming of the Son of man be."},{"ref":"Matthew 24:38","text":"For as in the days that were before the flood they were eating and drinking, marrying and giving in marriage, until the day that Noe entered into the ark,"},{"ref":"Matthew 24:39","text":"And knew not until the flood came, and took them all away; so shall also the coming of the Son of man be."},{"ref":"Matthew 24:40","text":"Then shall two be in the field; the one shall be taken, and the other left."},{"ref":"Matthew 24:41","text":"Two women shall be grinding at the mill; the one shall be taken, and the other left."},{"ref":"Matthew 24:42","text":"# Watch therefore: for ye know not what hour your Lord doth come."},{"ref":"Matthew 24:43","text":"But know this, that if the goodman of the house had known in what watch the thief would come, he would have watched, and would not have suffered his house to be broken up."},{"ref":"Matthew 24:44","text":"Therefore be ye also ready: for in such an hour as ye think not the Son of man cometh."},{"ref":"Matthew 24:45","text":"Who then is a faithful and wise servant, whom his lord hath made ruler over his household, to give them meat in due season?"},{"ref":"Matthew 24:46","text":"Blessed is that servant, whom his lord when he cometh shall find so doing."},{"ref":"Matthew 24:47","text":"Verily I say unto you, That he shall make him ruler over all his goods."},{"ref":"Matthew 24:48","text":"But and if that evil servant shall say in his heart, My lord delayeth his coming;"},{"ref":"Matthew 24:49","text":"And shall begin to smite his fellowservants, and to eat and drink with the drunken;"},{"ref":"Matthew 24:50","text":"The lord of that servant shall come in a day when he looketh not for him, and in an hour that he is not aware of,"},{"ref":"Matthew 24:51","text":"And shall cut him asunder, and appoint him his portion with the hypocrites: there shall be weeping and gnashing of teeth."}],"WEB":[{"ref":"Matthew 24:1","text":"Jesus went out from the temple, and was going on his way. His disciples came to him to show him the buildings of the temple."},{"ref":"Matthew 24:2","text":"But he answered them, “You see all of these things, don’t you? Most certainly I tell you, there will not be left here one stone on another, that will not be thrown down.”"},{"ref":"Matthew 24:3","text":"As he sat on the Mount of Olives, the disciples came to him privately, saying, “Tell us, when will these things be? What is the sign of your coming, and of the end of the age?”"},{"ref":"Matthew 24:4","text":"Jesus answered them, “Be careful that no one leads you astray."},{"ref":"Matthew 24:5","text":"For many will come in my name, saying, ‘I am the Christ,’ and will lead many astray."},{"ref":"Matthew 24:6","text":"You will hear of wars and rumors of wars. See that you aren’t troubled, for all this must happen, but the end is not yet."},{"ref":"Matthew 24:7","text":"For nation will rise against nation, and kingdom against kingdom; and there will be famines, plagues, and earthquakes in various places."},{"ref":"Matthew 24:8","text":"But all these things are the beginning of birth pains."},{"ref":"Matthew 24:9","text":"Then they will deliver you up to oppression, and will kill you. You will be hated by all of the nations for my name’s sake."},{"ref":"Matthew 24:10","text":"Then many will stumble, and will deliver up one another, and will hate one another."},{"ref":"Matthew 24:11","text":"Many false prophets will arise, and will lead many astray."},{"ref":"Matthew 24:12","text":"Because iniquity will be multiplied, the love of many will grow cold."},{"ref":"Matthew 24:13","text":"But he who endures to the end will be saved."},{"ref":"Matthew 24:14","text":"This Good News of the Kingdom will be preached in the whole world for a testimony to all the nations, and then the end will come."},{"ref":"Matthew 24:15","text":"“When, therefore, you see the abomination of desolation, which was spoken of through Daniel the prophet, standing in the holy place (let the reader understand),"},{"ref":"Matthew 24:16","text":"then let those who are in Judea flee to the mountains."},{"ref":"Matthew 24:17","text":"Let him who is on the housetop not go down to take out the things that are in his house."},{"ref":"Matthew 24:18","text":"Let him who is in the field not return back to get his clothes."},{"ref":"Matthew 24:19","text":"But woe to those who are with child and to nursing mothers in those days!"},{"ref":"Matthew 24:20","text":"Pray that your flight will not be in the winter, nor on a Sabbath,"},{"ref":"Matthew 24:21","text":"for then there will be great suffering, such as has not been from the beginning of the world until now, no, nor ever will be."},{"ref":"Matthew 24:22","text":"Unless those days had been shortened, no flesh would have been saved. But for the sake of the chosen ones, those days will be shortened."},{"ref":"Matthew 24:23","text":"“Then if any man tells you, ‘Behold, here is the Christ,’ or, ‘There,’ don’t believe it."},{"ref":"Matthew 24:24","text":"For there will arise false christs, and false prophets, and they will show great signs and wonders, so as to lead astray, if possible, even the chosen ones."},{"ref":"Matthew 24:25","text":"“Behold, I have told you beforehand."},{"ref":"Matthew 24:26","text":"If therefore they tell you, ‘Behold, he is in the wilderness,’ don’t go out; or ‘Behold, he is in the inner rooms,’ don’t believe it."},{"ref":"Matthew 24:27","text":"For as the lightning flashes from the east, and is seen even to the west, so will the coming of the Son of Man be."},{"ref":"Matthew 24:28","text":"For wherever the carcass is, that is where the vultures gather together."},{"ref":"Matthew 24:29","text":"But immediately after the suffering of those days, the sun will be darkened, the moon will not give its light, the stars will fall from the sky, and the powers of the heavens will be shaken;"},{"ref":"Matthew 24:30","text":"and then the sign of the Son of Man will appear in the sky. Then all the tribes of the earth will mourn, and they will see the Son of Man coming on the clouds of the sky with power and great glory."},{"ref":"Matthew 24:31","text":"He will send out his angels with a great sound of a trumpet, and they will gather together his chosen ones from the four winds, from one end of the sky to the other."},{"ref":"Matthew 24:32","text":"“Now from the fig tree learn this parable. When its branch has now become tender, and produces its leaves, you know that the summer is near."},{"ref":"Matthew 24:33","text":"Even so you also, when you see all these things, know that it is near, even at the doors."},{"ref":"Matthew 24:34","text":"Most certainly I tell you, this generation will not pass away, until all these things are accomplished."},{"ref":"Matthew 24:35","text":"Heaven and earth will pass away, but my words will not pass away."},{"ref":"Matthew 24:36","text":"But no one knows of that day and hour, not even the angels of heaven, but my Father only."},{"ref":"Matthew 24:37","text":"“As the days of Noah were, so will the coming of the Son of Man be."},{"ref":"Matthew 24:38","text":"For as in those days which were before the flood they were eating and drinking, marrying and giving in marriage, until the day that Noah entered into the ship,"},{"ref":"Matthew 24:39","text":"and they didn’t know until the flood came, and took them all away, so will the coming of the Son of Man be."},{"ref":"Matthew 24:40","text":"Then two men will be in the field: one will be taken and one will be left."},{"ref":"Matthew 24:41","text":"Two women will be grinding at the mill: one will be taken and one will be left."},{"ref":"Matthew 24:42","text":"Watch therefore, for you don’t know in what hour your Lord comes."},{"ref":"Matthew 24:43","text":"But know this, that if the master of the house had known in what watch of the night the thief was coming, he would have watched, and would not have allowed his house to be broken into."},{"ref":"Matthew 24:44","text":"Therefore also be ready, for in an hour that you don’t expect, the Son of Man will come."},{"ref":"Matthew 24:45","text":"“Who then is the faithful and wise servant, whom his lord has set over his household, to give them their food in due season?"},{"ref":"Matthew 24:46","text":"Blessed is that servant whom his lord finds doing so when he comes."},{"ref":"Matthew 24:47","text":"Most certainly I tell you that he will set him over all that he has."},{"ref":"Matthew 24:48","text":"But if that evil servant should say in his heart, ‘My lord is delaying his coming,’"},{"ref":"Matthew 24:49","text":"and begins to beat his fellow servants, and eat and drink with the drunkards,"},{"ref":"Matthew 24:50","text":"the lord of that servant will come in a day when he doesn’t expect it, and in an hour when he doesn’t know it,"},{"ref":"Matthew 24:51","text":"and will cut him in pieces, and appoint his portion with the hypocrites. That is where the weeping and grinding of teeth will be."}]},"mark-13":{"BSB":[{"ref":"Mark 13:1","text":"As Jesus was leaving the temple, one of His disciples said to Him, “Teacher, look at the magnificent stones and buildings!”"},{"ref":"Mark 13:2","text":"“Do you see all these great buildings?” Jesus replied. “Not one stone here will be left on another; every one will be thrown down.”"},{"ref":"Mark 13:3","text":"While Jesus was sitting on the Mount of Olives opposite the temple, Peter, James, John, and Andrew asked Him privately,"},{"ref":"Mark 13:4","text":"“Tell us, when will these things happen? And what will be the sign that they are about to be fulfilled?”"},{"ref":"Mark 13:5","text":"Jesus began by telling them, “See to it that no one deceives you."},{"ref":"Mark 13:6","text":"Many will come in My name, claiming, ‘I am He,’ and will deceive many."},{"ref":"Mark 13:7","text":"When you hear of wars and rumors of wars, do not be alarmed. These things must happen, but the end is still to come."},{"ref":"Mark 13:8","text":"Nation will rise against nation, and kingdom against kingdom. There will be earthquakes in various places, as well as famines. These are the beginning of birth pains."},{"ref":"Mark 13:9","text":"So be on your guard. You will be delivered over to the councils and beaten in the synagogues. On My account you will stand before governors and kings as witnesses to them."},{"ref":"Mark 13:10","text":"And the gospel must first be proclaimed to all the nations."},{"ref":"Mark 13:11","text":"But when they arrest you and hand you over, do not worry beforehand what to say. Instead, speak whatever you are given at that time, for it will not be you speaking, but the Holy Spirit."},{"ref":"Mark 13:12","text":"Brother will betray brother to death, and a father his child. Children will rise against their parents and have them put to death."},{"ref":"Mark 13:13","text":"You will be hated by everyone because of My name, but the one who perseveres to the end will be saved."},{"ref":"Mark 13:14","text":"So when you see the abomination of desolation standing where it should not be (let the reader understand), then let those who are in Judea flee to the mountains."},{"ref":"Mark 13:15","text":"Let no one on the housetop go back inside to retrieve anything from his house."},{"ref":"Mark 13:16","text":"And let no one in the field return for his cloak."},{"ref":"Mark 13:17","text":"How miserable those days will be for pregnant and nursing mothers!"},{"ref":"Mark 13:18","text":"Pray that this will not occur in the winter."},{"ref":"Mark 13:19","text":"For those will be days of tribulation unmatched from the beginning of God’s creation until now, and never to be seen again."},{"ref":"Mark 13:20","text":"If the Lord had not cut short those days, nobody would be saved. But for the sake of the elect, whom He has chosen, He has cut them short."},{"ref":"Mark 13:21","text":"At that time if anyone says to you, ‘Look, here is the Christ!’ or ‘There He is!’ do not believe it."},{"ref":"Mark 13:22","text":"For false Christs and false prophets will appear and perform signs and wonders that would deceive even the elect, if that were possible."},{"ref":"Mark 13:23","text":"So be on your guard; I have told you everything in advance."},{"ref":"Mark 13:24","text":"But in those days, after that tribulation: ‘The sun will be darkened, and the moon will not give its light;"},{"ref":"Mark 13:25","text":"the stars will fall from the sky, and the powers of the heavens will be shaken.’"},{"ref":"Mark 13:26","text":"At that time they will see the Son of Man coming in the clouds with great power and glory."},{"ref":"Mark 13:27","text":"And He will send out the angels to gather His elect from the four winds, from the ends of the earth to the ends of heaven."},{"ref":"Mark 13:28","text":"Now learn this lesson from the fig tree: As soon as its branches become tender and sprout leaves, you know that summer is near."},{"ref":"Mark 13:29","text":"So also, when you see these things happening, know that He is near, right at the door."},{"ref":"Mark 13:30","text":"Truly I tell you, this generation will not pass away until all these things have happened."},{"ref":"Mark 13:31","text":"Heaven and earth will pass away, but My words will never pass away."},{"ref":"Mark 13:32","text":"No one knows about that day or hour, not even the angels in heaven, nor the Son, but only the Father."},{"ref":"Mark 13:33","text":"Be on your guard and stay alert! For you do not know when the appointed time will come."},{"ref":"Mark 13:34","text":"It is like a man going on a journey who left his house, put each servant in charge of his own task, and instructed the doorkeeper to keep watch."},{"ref":"Mark 13:35","text":"Therefore keep watch, because you do not know when the master of the house will return—whether in the evening, at midnight, when the rooster crows, or in the morning."},{"ref":"Mark 13:36","text":"Otherwise, he may arrive without notice and find you sleeping."},{"ref":"Mark 13:37","text":"And what I say to you, I say to everyone: Keep watch!”"}],"KJV":[{"ref":"Mark 13:1","text":"And as he went out of the temple, one of his disciples saith unto him, Master, see what manner of stones and what buildings are here!"},{"ref":"Mark 13:2","text":"And Jesus answering said unto him, Seest thou these great buildings? there shall not be left one stone upon another, that shall not be thrown down."},{"ref":"Mark 13:3","text":"And as he sat upon the mount of Olives over against the temple, Peter and James and John and Andrew asked him privately,"},{"ref":"Mark 13:4","text":"Tell us, when shall these things be? and what shall be the sign when all these things shall be fulfilled?"},{"ref":"Mark 13:5","text":"And Jesus answering them began to say, Take heed lest any man deceive you:"},{"ref":"Mark 13:6","text":"For many shall come in my name, saying, I am Christ; and shall deceive many."},{"ref":"Mark 13:7","text":"And when ye shall hear of wars and rumours of wars, be ye not troubled: for such things must needs be; but the end shall not be yet."},{"ref":"Mark 13:8","text":"For nation shall rise against nation, and kingdom against kingdom: and there shall be earthquakes in divers places, and there shall be famines and troubles: these are the beginnings of sorrows."},{"ref":"Mark 13:9","text":"# But take heed to yourselves: for they shall deliver you up to councils; and in the synagogues ye shall be beaten: and ye shall be brought before rulers and kings for my sake, for a testimony against them."},{"ref":"Mark 13:10","text":"And the gospel must first be published among all nations."},{"ref":"Mark 13:11","text":"But when they shall lead you, and deliver you up, take no thought beforehand what ye shall speak, neither do ye premeditate: but whatsoever shall be given you in that hour, that speak ye: for it is not ye that speak, but the Holy Ghost."},{"ref":"Mark 13:12","text":"Now the brother shall betray the brother to death, and the father the son; and children shall rise up against their parents, and shall cause them to be put to death."},{"ref":"Mark 13:13","text":"And ye shall be hated of all men for my name's sake: but he that shall endure unto the end, the same shall be saved."},{"ref":"Mark 13:14","text":"# But when ye shall see the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not, (let him that readeth understand,) then let them that be in Judaea flee to the mountains:"},{"ref":"Mark 13:15","text":"And let him that is on the housetop not go down into the house, neither enter therein, to take any thing out of his house:"},{"ref":"Mark 13:16","text":"And let him that is in the field not turn back again for to take up his garment."},{"ref":"Mark 13:17","text":"But woe to them that are with child, and to them that give suck in those days!"},{"ref":"Mark 13:18","text":"And pray ye that your flight be not in the winter."},{"ref":"Mark 13:19","text":"For in those days shall be affliction, such as was not from the beginning of the creation which God created unto this time, neither shall be."},{"ref":"Mark 13:20","text":"And except that the Lord had shortened those days, no flesh should be saved: but for the elect's sake, whom he hath chosen, he hath shortened the days."},{"ref":"Mark 13:21","text":"And then if any man shall say to you, Lo, here is Christ; or, lo, he is there; believe him not:"},{"ref":"Mark 13:22","text":"For false Christs and false prophets shall rise, and shall shew signs and wonders, to seduce, if it were possible, even the elect."},{"ref":"Mark 13:23","text":"But take ye heed: behold, I have foretold you all things."},{"ref":"Mark 13:24","text":"# But in those days, after that tribulation, the sun shall be darkened, and the moon shall not give her light,"},{"ref":"Mark 13:25","text":"And the stars of heaven shall fall, and the powers that are in heaven shall be shaken."},{"ref":"Mark 13:26","text":"And then shall they see the Son of man coming in the clouds with great power and glory."},{"ref":"Mark 13:27","text":"And then shall he send his angels, and shall gather together his elect from the four winds, from the uttermost part of the earth to the uttermost part of heaven."},{"ref":"Mark 13:28","text":"Now learn a parable of the fig tree; When her branch is yet tender, and putteth forth leaves, ye know that summer is near:"},{"ref":"Mark 13:29","text":"So ye in like manner, when ye shall see these things come to pass, know that it is nigh, even at the doors."},{"ref":"Mark 13:30","text":"Verily I say unto you, that this generation shall not pass, till all these things be done."},{"ref":"Mark 13:31","text":"Heaven and earth shall pass away: but my words shall not pass away."},{"ref":"Mark 13:32","text":"# But of that day and that hour knoweth no man, no, not the angels which are in heaven, neither the Son, but the Father."},{"ref":"Mark 13:33","text":"Take ye heed, watch and pray: for ye know not when the time is."},{"ref":"Mark 13:34","text":"For the Son of man is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch."},{"ref":"Mark 13:35","text":"Watch ye therefore: for ye know not when the master of the house cometh, at even, or at midnight, or at the cockcrowing, or in the morning:"},{"ref":"Mark 13:36","text":"Lest coming suddenly he find you sleeping."},{"ref":"Mark 13:37","text":"And what I say unto you I say unto all, Watch."}],"WEB":[{"ref":"Mark 13:1","text":"As he went out of the temple, one of his disciples said to him, “Teacher, see what kind of stones and what kind of buildings!”"},{"ref":"Mark 13:2","text":"Jesus said to him, “Do you see these great buildings? There will not be left here one stone on another, which will not be thrown down.”"},{"ref":"Mark 13:3","text":"As he sat on the Mount of Olives opposite the temple, Peter, James, John, and Andrew asked him privately,"},{"ref":"Mark 13:4","text":"“Tell us, when will these things be? What is the sign that these things are all about to be fulfilled?”"},{"ref":"Mark 13:5","text":"Jesus, answering, began to tell them, “Be careful that no one leads you astray."},{"ref":"Mark 13:6","text":"For many will come in my name, saying, ‘I am he!’ and will lead many astray."},{"ref":"Mark 13:7","text":"“When you hear of wars and rumors of wars, don’t be troubled. For those must happen, but the end is not yet."},{"ref":"Mark 13:8","text":"For nation will rise against nation, and kingdom against kingdom. There will be earthquakes in various places. There will be famines and troubles. These things are the beginning of birth pains."},{"ref":"Mark 13:9","text":"But watch yourselves, for they will deliver you up to councils. You will be beaten in synagogues. You will stand before rulers and kings for my sake, for a testimony to them."},{"ref":"Mark 13:10","text":"The Good News must first be preached to all the nations."},{"ref":"Mark 13:11","text":"When they lead you away and deliver you up, don’t be anxious beforehand, or premeditate what you will say, but say whatever will be given you in that hour. For it is not you who speak, but the Holy Spirit."},{"ref":"Mark 13:12","text":"“Brother will deliver up brother to death, and the father his child. Children will rise up against parents, and cause them to be put to death."},{"ref":"Mark 13:13","text":"You will be hated by all men for my name’s sake, but he who endures to the end will be saved."},{"ref":"Mark 13:14","text":"But when you see the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not” (let the reader understand), “then let those who are in Judea flee to the mountains,"},{"ref":"Mark 13:15","text":"and let him who is on the housetop not go down, nor enter in, to take anything out of his house."},{"ref":"Mark 13:16","text":"Let him who is in the field not return back to take his cloak."},{"ref":"Mark 13:17","text":"But woe to those who are with child and to those who nurse babies in those days!"},{"ref":"Mark 13:18","text":"Pray that your flight won’t be in the winter."},{"ref":"Mark 13:19","text":"For in those days there will be oppression, such as there has not been the like from the beginning of the creation which God created until now, and never will be."},{"ref":"Mark 13:20","text":"Unless the Lord had shortened the days, no flesh would have been saved; but for the sake of the chosen ones, whom he picked out, he shortened the days."},{"ref":"Mark 13:21","text":"Then if anyone tells you, ‘Look, here is the Christ!’ or, ‘Look, there!’ don’t believe it."},{"ref":"Mark 13:22","text":"For there will arise false christs and false prophets, and will show signs and wonders, that they may lead astray, if possible, even the chosen ones."},{"ref":"Mark 13:23","text":"But you watch. “Behold, I have told you all things beforehand."},{"ref":"Mark 13:24","text":"But in those days, after that oppression, the sun will be darkened, the moon will not give its light,"},{"ref":"Mark 13:25","text":"the stars will be falling from the sky, and the powers that are in the heavens will be shaken."},{"ref":"Mark 13:26","text":"Then they will see the Son of Man coming in clouds with great power and glory."},{"ref":"Mark 13:27","text":"Then he will send out his angels, and will gather together his chosen ones from the four winds, from the ends of the earth to the ends of the sky."},{"ref":"Mark 13:28","text":"“Now from the fig tree, learn this parable. When the branch has now become tender, and produces its leaves, you know that the summer is near;"},{"ref":"Mark 13:29","text":"even so you also, when you see these things coming to pass, know that it is near, at the doors."},{"ref":"Mark 13:30","text":"Most certainly I say to you, this generation will not pass away until all these things happen."},{"ref":"Mark 13:31","text":"Heaven and earth will pass away, but my words will not pass away."},{"ref":"Mark 13:32","text":"But of that day or that hour no one knows, not even the angels in heaven, nor the Son, but only the Father."},{"ref":"Mark 13:33","text":"Watch, keep alert, and pray; for you don’t know when the time is."},{"ref":"Mark 13:34","text":"“It is like a man, traveling to another country, having left his house, and given authority to his servants, and to each one his work, and also commanded the doorkeeper to keep watch."},{"ref":"Mark 13:35","text":"Watch therefore, for you don’t know when the lord of the house is coming, whether at evening, or at midnight, or when the rooster crows, or in the morning;"},{"ref":"Mark 13:36","text":"lest coming suddenly he might find you sleeping."},{"ref":"Mark 13:37","text":"What I tell you, I tell all: Watch.”"}]},"luke-21":{"BSB":[{"ref":"Luke 21:5","text":"As some of the disciples were remarking how the temple was adorned with beautiful stones and consecrated gifts, Jesus said,"},{"ref":"Luke 21:6","text":"“As for what you see here, the time will come when not one stone will be left on another; every one will be thrown down.”"},{"ref":"Luke 21:7","text":"“Teacher,” they asked, “when will these things happen? And what will be the sign that they are about to take place?”"},{"ref":"Luke 21:8","text":"Jesus answered, “See to it that you are not deceived. For many will come in My name, claiming, ‘I am He,’ and, ‘The time is near.’ Do not follow them."},{"ref":"Luke 21:9","text":"When you hear of wars and rebellions, do not be alarmed. These things must happen first, but the end is not imminent.”"},{"ref":"Luke 21:10","text":"Then He told them, “Nation will rise against nation, and kingdom against kingdom."},{"ref":"Luke 21:11","text":"There will be great earthquakes, famines, and pestilences in various places, along with fearful sights and great signs from heaven."},{"ref":"Luke 21:12","text":"But before all this, they will seize you and persecute you. On account of My name they will deliver you to the synagogues and prisons, and they will bring you before kings and governors."},{"ref":"Luke 21:13","text":"This will be your opportunity to serve as witnesses."},{"ref":"Luke 21:14","text":"So make up your mind not to worry beforehand how to defend yourselves."},{"ref":"Luke 21:15","text":"For I will give you speech and wisdom that none of your adversaries will be able to resist or contradict."},{"ref":"Luke 21:16","text":"You will be betrayed even by parents and brothers and relatives and friends, and some of you will be put to death."},{"ref":"Luke 21:17","text":"And you will be hated by everyone because of My name."},{"ref":"Luke 21:18","text":"Yet not even a hair of your head will perish."},{"ref":"Luke 21:19","text":"By your patient endurance you will gain your souls."},{"ref":"Luke 21:20","text":"But when you see Jerusalem surrounded by armies, you will know that her desolation is near."},{"ref":"Luke 21:21","text":"Then let those who are in Judea flee to the mountains, let those in the city get out, and let those in the country stay out of the city."},{"ref":"Luke 21:22","text":"For these are the days of vengeance, to fulfill all that is written."},{"ref":"Luke 21:23","text":"How miserable those days will be for pregnant and nursing mothers! For there will be great distress upon the land and wrath against this people."},{"ref":"Luke 21:24","text":"They will fall by the edge of the sword and be led captive into all the nations. And Jerusalem will be trodden down by the Gentiles, until the times of the Gentiles are fulfilled."},{"ref":"Luke 21:25","text":"There will be signs in the sun and moon and stars, and on the earth dismay among the nations, bewildered by the roaring of the sea and the surging of the waves."},{"ref":"Luke 21:26","text":"Men will faint from fear and anxiety over what is coming upon the earth, for the powers of the heavens will be shaken."},{"ref":"Luke 21:27","text":"At that time they will see the Son of Man coming in a cloud with power and great glory."},{"ref":"Luke 21:28","text":"When these things begin to happen, stand up and lift up your heads, because your redemption is drawing near.”"},{"ref":"Luke 21:29","text":"Then Jesus told them a parable: “Look at the fig tree and all the trees."},{"ref":"Luke 21:30","text":"When they sprout leaves, you can see for yourselves and know that summer is near."},{"ref":"Luke 21:31","text":"So also, when you see these things happening, know that the kingdom of God is near."},{"ref":"Luke 21:32","text":"Truly I tell you, this generation will not pass away until all these things have happened."},{"ref":"Luke 21:33","text":"Heaven and earth will pass away, but My words will never pass away."},{"ref":"Luke 21:34","text":"But watch yourselves, or your hearts will be weighed down by dissipation, drunkenness, and the worries of life—and that day will spring upon you suddenly like a snare."},{"ref":"Luke 21:35","text":"For it will come upon all who dwell on the face of all the earth."},{"ref":"Luke 21:36","text":"So keep watch at all times, and pray that you may have the strength to escape all that is about to happen and to stand before the Son of Man.”"}],"KJV":[{"ref":"Luke 21:5","text":"# And as some spake of the temple, how it was adorned with goodly stones and gifts, he said,"},{"ref":"Luke 21:6","text":"As for these things which ye behold, the days will come, in the which there shall not be left one stone upon another, that shall not be thrown down."},{"ref":"Luke 21:7","text":"And they asked him, saying, Master, but when shall these things be? and what sign will there be when these things shall come to pass?"},{"ref":"Luke 21:8","text":"And he said, Take heed that ye be not deceived: for many shall come in my name, saying, I am Christ; and the time draweth near: go ye not therefore after them."},{"ref":"Luke 21:9","text":"But when ye shall hear of wars and commotions, be not terrified: for these things must first come to pass; but the end is not by and by."},{"ref":"Luke 21:10","text":"Then said he unto them, Nation shall rise against nation, and kingdom against kingdom:"},{"ref":"Luke 21:11","text":"And great earthquakes shall be in divers places, and famines, and pestilences; and fearful sights and great signs shall there be from heaven."},{"ref":"Luke 21:12","text":"But before all these, they shall lay their hands on you, and persecute you, delivering you up to the synagogues, and into prisons, being brought before kings and rulers for my name's sake."},{"ref":"Luke 21:13","text":"And it shall turn to you for a testimony."},{"ref":"Luke 21:14","text":"Settle it therefore in your hearts, not to meditate before what ye shall answer:"},{"ref":"Luke 21:15","text":"For I will give you a mouth and wisdom, which all your adversaries shall not be able to gainsay nor resist."},{"ref":"Luke 21:16","text":"And ye shall be betrayed both by parents, and brethren, and kinsfolks, and friends; and some of you shall they cause to be put to death."},{"ref":"Luke 21:17","text":"And ye shall be hated of all men for my name's sake."},{"ref":"Luke 21:18","text":"But there shall not an hair of your head perish."},{"ref":"Luke 21:19","text":"In your patience possess ye your souls."},{"ref":"Luke 21:20","text":"And when ye shall see Jerusalem compassed with armies, then know that the desolation thereof is nigh."},{"ref":"Luke 21:21","text":"Then let them which are in Judaea flee to the mountains; and let them which are in the midst of it depart out; and let not them that are in the countries enter thereinto."},{"ref":"Luke 21:22","text":"For these be the days of vengeance, that all things which are written may be fulfilled."},{"ref":"Luke 21:23","text":"But woe unto them that are with child, and to them that give suck, in those days! for there shall be great distress in the land, and wrath upon this people."},{"ref":"Luke 21:24","text":"And they shall fall by the edge of the sword, and shall be led away captive into all nations: and Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled."},{"ref":"Luke 21:25","text":"# And there shall be signs in the sun, and in the moon, and in the stars; and upon the earth distress of nations, with perplexity; the sea and the waves roaring;"},{"ref":"Luke 21:26","text":"Men's hearts failing them for fear, and for looking after those things which are coming on the earth: for the powers of heaven shall be shaken."},{"ref":"Luke 21:27","text":"And then shall they see the Son of man coming in a cloud with power and great glory."},{"ref":"Luke 21:28","text":"And when these things begin to come to pass, then look up, and lift up your heads; for your redemption draweth nigh."},{"ref":"Luke 21:29","text":"And he spake to them a parable; Behold the fig tree, and all the trees;"},{"ref":"Luke 21:30","text":"When they now shoot forth, ye see and know of your own selves that summer is now nigh at hand."},{"ref":"Luke 21:31","text":"So likewise ye, when ye see these things come to pass, know ye that the kingdom of God is nigh at hand."},{"ref":"Luke 21:32","text":"Verily I say unto you, This generation shall not pass away, till all be fulfilled."},{"ref":"Luke 21:33","text":"Heaven and earth shall pass away: but my words shall not pass away."},{"ref":"Luke 21:34","text":"# And take heed to yourselves, lest at any time your hearts be overcharged with surfeiting, and drunkenness, and cares of this life, and so that day come upon you unawares."},{"ref":"Luke 21:35","text":"For as a snare shall it come on all them that dwell on the face of the whole earth."},{"ref":"Luke 21:36","text":"Watch ye therefore, and pray always, that ye may be accounted worthy to escape all these things that shall come to pass, and to stand before the Son of man."}],"WEB":[{"ref":"Luke 21:5","text":"As some were talking about the temple and how it was decorated with beautiful stones and gifts, he said,"},{"ref":"Luke 21:6","text":"“As for these things which you see, the days will come, in which there will not be left here one stone on another that will not be thrown down.”"},{"ref":"Luke 21:7","text":"They asked him, “Teacher, so when will these things be? What is the sign that these things are about to happen?”"},{"ref":"Luke 21:8","text":"He said, “Watch out that you don’t get led astray, for many will come in my name, saying, ‘I am he,’ and, ‘The time is at hand.’ Therefore don’t follow them."},{"ref":"Luke 21:9","text":"When you hear of wars and disturbances, don’t be terrified, for these things must happen first, but the end won’t come immediately.”"},{"ref":"Luke 21:10","text":"Then he said to them, “Nation will rise against nation, and kingdom against kingdom."},{"ref":"Luke 21:11","text":"There will be great earthquakes, famines, and plagues in various places. There will be terrors and great signs from heaven."},{"ref":"Luke 21:12","text":"But before all these things, they will lay their hands on you and will persecute you, delivering you up to synagogues and prisons, bringing you before kings and governors for my name’s sake."},{"ref":"Luke 21:13","text":"It will turn out as a testimony for you."},{"ref":"Luke 21:14","text":"Settle it therefore in your hearts not to meditate beforehand how to answer,"},{"ref":"Luke 21:15","text":"for I will give you a mouth and wisdom which all your adversaries will not be able to withstand or to contradict."},{"ref":"Luke 21:16","text":"You will be handed over even by parents, brothers, relatives, and friends. They will cause some of you to be put to death."},{"ref":"Luke 21:17","text":"You will be hated by all men for my name’s sake."},{"ref":"Luke 21:18","text":"And not a hair of your head will perish."},{"ref":"Luke 21:19","text":"“By your endurance you will win your lives."},{"ref":"Luke 21:20","text":"“But when you see Jerusalem surrounded by armies, then know that its desolation is at hand."},{"ref":"Luke 21:21","text":"Then let those who are in Judea flee to the mountains. Let those who are in the middle of her depart. Let those who are in the country not enter therein."},{"ref":"Luke 21:22","text":"For these are days of vengeance, that all things which are written may be fulfilled."},{"ref":"Luke 21:23","text":"Woe to those who are pregnant and to those who nurse infants in those days! For there will be great distress in the land, and wrath to this people."},{"ref":"Luke 21:24","text":"They will fall by the edge of the sword, and will be led captive into all the nations. Jerusalem will be trampled down by the Gentiles, until the times of the Gentiles are fulfilled."},{"ref":"Luke 21:25","text":"There will be signs in the sun, moon, and stars; and on the earth anxiety of nations, in perplexity for the roaring of the sea and the waves;"},{"ref":"Luke 21:26","text":"men fainting for fear, and for expectation of the things which are coming on the world: for the powers of the heavens will be shaken."},{"ref":"Luke 21:27","text":"Then they will see the Son of Man coming in a cloud with power and great glory."},{"ref":"Luke 21:28","text":"But when these things begin to happen, look up and lift up your heads, because your redemption is near.”"},{"ref":"Luke 21:29","text":"He told them a parable. “See the fig tree and all the trees."},{"ref":"Luke 21:30","text":"When they are already budding, you see it and know by your own selves that the summer is already near."},{"ref":"Luke 21:31","text":"Even so you also, when you see these things happening, know that God’s Kingdom is near."},{"ref":"Luke 21:32","text":"Most certainly I tell you, this generation will not pass away until all things are accomplished."},{"ref":"Luke 21:33","text":"Heaven and earth will pass away, but my words will by no means pass away."},{"ref":"Luke 21:34","text":"“So be careful, or your hearts will be loaded down with carousing, drunkenness, and cares of this life, and that day will come on you suddenly."},{"ref":"Luke 21:35","text":"For it will come like a snare on all those who dwell on the surface of all the earth."},{"ref":"Luke 21:36","text":"Therefore be watchful all the time, praying that you may be counted worthy to escape all these things that will happen, and to stand before the Son of Man.”"}]},"daniel-2":{"BSB":[{"ref":"Daniel 2:31","text":"As you, O king, were watching, a great statue appeared. A great and dazzling statue stood before you, and its form was awesome."},{"ref":"Daniel 2:32","text":"The head of the statue was pure gold, its chest and arms were silver, its belly and thighs were bronze,"},{"ref":"Daniel 2:33","text":"its legs were iron, and its feet were part iron and part clay."},{"ref":"Daniel 2:34","text":"As you watched, a stone was cut out, but not by human hands. It struck the statue on its feet of iron and clay, and crushed them."},{"ref":"Daniel 2:35","text":"Then the iron, clay, bronze, silver, and gold were shattered and became like chaff on the threshing floor in summer. The wind carried them away, and not a trace of them could be found. But the stone that had struck the statue became a great mountain and filled the whole earth."},{"ref":"Daniel 2:36","text":"This was the dream; now we will tell the king its interpretation."},{"ref":"Daniel 2:37","text":"You, O king, are the king of kings, to whom the God of heaven has given sovereignty, power, strength, and glory."},{"ref":"Daniel 2:38","text":"Wherever the sons of men or beasts of the field or birds of the air dwell, He has given them into your hand and has made you ruler over them all. You are that head of gold."},{"ref":"Daniel 2:39","text":"But after you, there will arise another kingdom, inferior to yours. Next, a third kingdom, one of bronze, will rule the whole earth."},{"ref":"Daniel 2:40","text":"Finally, there will be a fourth kingdom as strong as iron; for iron shatters and crushes all things, and like iron that crushes all things, it will shatter and crush all the others."},{"ref":"Daniel 2:41","text":"And just as you saw that the feet and toes were made partly of fired clay and partly of iron, so this will be a divided kingdom, yet some of the strength of iron will be in it—just as you saw the iron mixed with clay."},{"ref":"Daniel 2:42","text":"And as the toes of the feet were partly iron and partly clay, so this kingdom will be partly strong and partly brittle."},{"ref":"Daniel 2:43","text":"As you saw the iron mixed with clay, so the peoples will mix with one another, but will not hold together any more than iron mixes with clay."},{"ref":"Daniel 2:44","text":"In the days of those kings, the God of heaven will set up a kingdom that will never be destroyed, nor will it be left to another people. It will shatter all these kingdoms and bring them to an end, but will itself stand forever."},{"ref":"Daniel 2:45","text":"And just as you saw a stone being cut out of the mountain without human hands, and it shattered the iron, bronze, clay, silver, and gold, so the great God has told the king what will happen in the future. The dream is true, and its interpretation is trustworthy.”"}],"KJV":[{"ref":"Daniel 2:31","text":"# Thou, O king, sawest, and behold a great image. This great image, whose brightness was excellent, stood before thee; and the form thereof was terrible."},{"ref":"Daniel 2:32","text":"This image's head was of fine gold, his breast and his arms of silver, his belly and his thighs of brass,"},{"ref":"Daniel 2:33","text":"His legs of iron, his feet part of iron and part of clay."},{"ref":"Daniel 2:34","text":"Thou sawest till that a stone was cut out without hands, which smote the image upon his feet that were of iron and clay, and brake them to pieces."},{"ref":"Daniel 2:35","text":"Then was the iron, the clay, the brass, the silver, and the gold, broken to pieces together, and became like the chaff of the summer threshingfloors; and the wind carried them away, that no place was found for them: and the stone that smote the image became a great mountain, and filled the whole earth."},{"ref":"Daniel 2:36","text":"# This is the dream; and we will tell the interpretation thereof before the king."},{"ref":"Daniel 2:37","text":"Thou, O king, art a king of kings: for the God of heaven hath given thee a kingdom, power, and strength, and glory."},{"ref":"Daniel 2:38","text":"And wheresoever the children of men dwell, the beasts of the field and the fowls of the heaven hath he given into thine hand, and hath made thee ruler over them all. Thou art this head of gold."},{"ref":"Daniel 2:39","text":"And after thee shall arise another kingdom inferior to thee, and another third kingdom of brass, which shall bear rule over all the earth."},{"ref":"Daniel 2:40","text":"And the fourth kingdom shall be strong as iron: forasmuch as iron breaketh in pieces and subdueth all things: and as iron that breaketh all these, shall it break in pieces and bruise."},{"ref":"Daniel 2:41","text":"And whereas thou sawest the feet and toes, part of potters' clay, and part of iron, the kingdom shall be divided; but there shall be in it of the strength of the iron, forasmuch as thou sawest the iron mixed with miry clay."},{"ref":"Daniel 2:42","text":"And as the toes of the feet were part of iron, and part of clay, so the kingdom shall be partly strong, and partly broken."},{"ref":"Daniel 2:43","text":"And whereas thou sawest iron mixed with miry clay, they shall mingle themselves with the seed of men: but they shall not cleave one to another, even as iron is not mixed with clay."},{"ref":"Daniel 2:44","text":"And in the days of these kings shall the God of heaven set up a kingdom, which shall never be destroyed: and the kingdom shall not be left to other people, but it shall break in pieces and consume all these kingdoms, and it shall stand for ever."},{"ref":"Daniel 2:45","text":"Forasmuch as thou sawest that the stone was cut out of the mountain without hands, and that it brake in pieces the iron, the brass, the clay, the silver, and the gold; the great God hath made known to the king what shall come to pass hereafter: and the dream is certain, and the interpretation thereof sure."}],"WEB":[{"ref":"Daniel 2:31","text":"“You, O king, saw, and behold, a great image. This image, which was mighty, and whose brightness was excellent, stood before you; and its appearance was terrifying."},{"ref":"Daniel 2:32","text":"As for this image, its head was of fine gold, its breast and its arms of silver, its belly and its thighs of bronze,"},{"ref":"Daniel 2:33","text":"its legs of iron, its feet part of iron, and part of clay."},{"ref":"Daniel 2:34","text":"You saw until a stone was cut out without hands, which struck the image on its feet that were of iron and clay, and broke them in pieces."},{"ref":"Daniel 2:35","text":"Then the iron, the clay, the bronze, the silver, and the gold were broken in pieces together, and became like the chaff of the summer threshing floors. The wind carried them away, so that no place was found for them. The stone that struck the image became a great mountain, and filled the whole earth."},{"ref":"Daniel 2:36","text":"“This is the dream; and we will tell its interpretation before the king."},{"ref":"Daniel 2:37","text":"You, O king, are king of kings, to whom the God of heaven has given the kingdom, the power, the strength, and the glory."},{"ref":"Daniel 2:38","text":"Wherever the children of men dwell, he has given the animals of the field and the birds of the sky into your hand, and has made you rule over them all. You are the head of gold."},{"ref":"Daniel 2:39","text":"“After you, another kingdom will arise that is inferior to you; and another third kingdom of bronze, which will rule over all the earth."},{"ref":"Daniel 2:40","text":"The fourth kingdom will be strong as iron, because iron breaks in pieces and subdues all things; and as iron that crushes all these, it will break in pieces and crush."},{"ref":"Daniel 2:41","text":"Whereas you saw the feet and toes, part of potters’ clay, and part of iron, it will be a divided kingdom; but there will be in it of the strength of the iron, because you saw the iron mixed with miry clay."},{"ref":"Daniel 2:42","text":"As the toes of the feet were part of iron, and part of clay, so the kingdom will be partly strong, and partly broken."},{"ref":"Daniel 2:43","text":"Whereas you saw the iron mixed with miry clay, they will mingle themselves with the seed of men; but they won’t cling to one another, even as iron does not mix with clay."},{"ref":"Daniel 2:44","text":"“In the days of those kings the God of heaven will set up a kingdom which will never be destroyed, nor will its sovereignty be left to another people; but it will break in pieces and consume all these kingdoms, and it will stand forever."},{"ref":"Daniel 2:45","text":"Because you saw that a stone was cut out of the mountain without hands, and that it broke in pieces the iron, the bronze, the clay, the silver, and the gold; the great God has made known to the king what will happen hereafter. The dream is certain, and its interpretation sure.”"}]},"daniel-7":{"BSB":[{"ref":"Daniel 7:1","text":"In the first year of the reign of Belshazzar over Babylon, Daniel had a dream, and visions passed through his mind as he lay on his bed. He wrote down the dream, and this is the summary of his account."},{"ref":"Daniel 7:2","text":"Daniel declared: “In my vision in the night I looked, and suddenly the four winds of heaven were churning up the great sea."},{"ref":"Daniel 7:3","text":"Then four great beasts came up out of the sea, each one different from the others:"},{"ref":"Daniel 7:4","text":"The first beast was like a lion, and it had the wings of an eagle. I watched until its wings were torn off and it was lifted up from the ground and made to stand on two feet like a man, and given the mind of a man."},{"ref":"Daniel 7:5","text":"Suddenly another beast appeared, which looked like a bear. It was raised up on one of its sides, and it had three ribs in its mouth between its teeth. So it was told, ‘Get up and gorge yourself on flesh!’"},{"ref":"Daniel 7:6","text":"Next, as I watched, another beast appeared. It was like a leopard, and on its back it had four wings like those of a bird. The beast also had four heads, and it was given authority to rule."},{"ref":"Daniel 7:7","text":"After this, as I watched in my vision in the night, suddenly a fourth beast appeared, and it was terrifying—dreadful and extremely strong—with large iron teeth. It devoured and crushed; then it trampled underfoot whatever was left. It was different from all the beasts before it, and it had ten horns."},{"ref":"Daniel 7:8","text":"While I was contemplating the horns, suddenly another horn, a little one, came up among them, and three of the first horns were uprooted before it. This horn had eyes like those of a man and a mouth that spoke words of arrogance."},{"ref":"Daniel 7:9","text":"As I continued to watch, thrones were set in place, and the Ancient of Days took His seat. His clothing was white as snow, and the hair of His head was like pure wool. His throne was flaming with fire, and its wheels were all ablaze."},{"ref":"Daniel 7:10","text":"A river of fire was flowing, coming out from His presence. Thousands upon thousands attended Him, and myriads upon myriads stood before Him. The court was convened, and the books were opened."},{"ref":"Daniel 7:11","text":"Then I kept watching because of the arrogant words the horn was speaking. As I continued to watch, the beast was slain, and its body was destroyed and thrown into the blazing fire."},{"ref":"Daniel 7:12","text":"As for the rest of the beasts, their dominion was removed, but they were granted an extension of life for a season and a time."},{"ref":"Daniel 7:13","text":"In my vision in the night I continued to watch, and I saw One like the Son of Man coming with the clouds of heaven. He approached the Ancient of Days and was led into His presence."},{"ref":"Daniel 7:14","text":"And He was given dominion, glory, and kingship, that the people of every nation and language should serve Him. His dominion is an everlasting dominion that will not pass away, and His kingdom is one that will never be destroyed."},{"ref":"Daniel 7:15","text":"I, Daniel, was grieved in my spirit, and the visions in my mind alarmed me."},{"ref":"Daniel 7:16","text":"I approached one of those who were standing there, and I asked him the true meaning of all this. So he told me the interpretation of these things:"},{"ref":"Daniel 7:17","text":"‘These four great beasts are four kings who will arise from the earth."},{"ref":"Daniel 7:18","text":"But the saints of the Most High will receive the kingdom and possess it forever—yes, forever and ever.’"},{"ref":"Daniel 7:19","text":"Then I wanted to know the true meaning of the fourth beast, which was different from all the others—extremely terrifying—devouring and crushing with iron teeth and bronze claws, then trampling underfoot whatever was left."},{"ref":"Daniel 7:20","text":"I also wanted to know about the ten horns on its head and the other horn that came up, before which three of them fell—the horn whose appearance was more imposing than the others, with eyes and with a mouth that spoke words of arrogance."},{"ref":"Daniel 7:21","text":"As I watched, this horn was waging war against the saints and prevailing against them,"},{"ref":"Daniel 7:22","text":"until the Ancient of Days arrived and pronounced judgment in favor of the saints of the Most High, and the time came for them to possess the kingdom."},{"ref":"Daniel 7:23","text":"This is what he said: ‘The fourth beast is a fourth kingdom that will appear on the earth, different from all the other kingdoms, and it will devour the whole earth, trample it down, and crush it."},{"ref":"Daniel 7:24","text":"And the ten horns are ten kings who will rise from this kingdom. After them another king, different from the earlier ones, will rise and subdue three kings."},{"ref":"Daniel 7:25","text":"He will speak out against the Most High and oppress the saints of the Most High, intending to change the appointed times and laws; and the saints will be given into his hand for a time, and times, and half a time."},{"ref":"Daniel 7:26","text":"But the court will convene, and his dominion will be taken away and completely destroyed forever."},{"ref":"Daniel 7:27","text":"Then the sovereignty, dominion, and greatness of the kingdoms under all of heaven will be given to the people, the saints of the Most High. His kingdom will be an everlasting kingdom, and all rulers will serve and obey Him.’"},{"ref":"Daniel 7:28","text":"Thus ends the matter. As for me, Daniel, my thoughts troubled me greatly, and my face turned pale. But I kept the matter to myself.”"}],"KJV":[{"ref":"Daniel 7:1","text":"In the first year of Belshazzar king of Babylon Daniel had a dream and visions of his head upon his bed: then he wrote the dream, and told the sum of the matters."},{"ref":"Daniel 7:2","text":"Daniel spake and said, I saw in my vision by night, and, behold, the four winds of the heaven strove upon the great sea."},{"ref":"Daniel 7:3","text":"And four great beasts came up from the sea, diverse one from another."},{"ref":"Daniel 7:4","text":"The first was like a lion, and had eagle's wings: I beheld till the wings thereof were plucked, and it was lifted up from the earth, and made stand upon the feet as a man, and a man's heart was given to it."},{"ref":"Daniel 7:5","text":"And behold another beast, a second, like to a bear, and it raised up itself on one side, and it had three ribs in the mouth of it between the teeth of it: and they said thus unto it, Arise, devour much flesh."},{"ref":"Daniel 7:6","text":"After this I beheld, and lo another, like a leopard, which had upon the back of it four wings of a fowl; the beast had also four heads; and dominion was given to it."},{"ref":"Daniel 7:7","text":"After this I saw in the night visions, and behold a fourth beast, dreadful and terrible, and strong exceedingly; and it had great iron teeth: it devoured and brake in pieces, and stamped the residue with the feet of it: and it was diverse from all the beasts that were before it; and it had ten horns."},{"ref":"Daniel 7:8","text":"I considered the horns, and, behold, there came up among them another little horn, before whom there were three of the first horns plucked up by the roots: and, behold, in this horn were eyes like the eyes of man, and a mouth speaking great things."},{"ref":"Daniel 7:9","text":"# I beheld till the thrones were cast down, and the Ancient of days did sit, whose garment was white as snow, and the hair of his head like the pure wool: his throne was like the fiery flame, and his wheels as burning fire."},{"ref":"Daniel 7:10","text":"A fiery stream issued and came forth from before him: thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened."},{"ref":"Daniel 7:11","text":"I beheld then because of the voice of the great words which the horn spake: I beheld even till the beast was slain, and his body destroyed, and given to the burning flame."},{"ref":"Daniel 7:12","text":"As concerning the rest of the beasts, they had their dominion taken away: yet their lives were prolonged for a season and time."},{"ref":"Daniel 7:13","text":"I saw in the night visions, and, behold, one like the Son of man came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him."},{"ref":"Daniel 7:14","text":"And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed."},{"ref":"Daniel 7:15","text":"# I Daniel was grieved in my spirit in the midst of my body, and the visions of my head troubled me."},{"ref":"Daniel 7:16","text":"I came near unto one of them that stood by, and asked him the truth of all this. So he told me, and made me know the interpretation of the things."},{"ref":"Daniel 7:17","text":"These great beasts, which are four, are four kings, which shall arise out of the earth."},{"ref":"Daniel 7:18","text":"But the saints of the most High shall take the kingdom, and possess the kingdom for ever, even for ever and ever."},{"ref":"Daniel 7:19","text":"Then I would know the truth of the fourth beast, which was diverse from all the others, exceeding dreadful, whose teeth were of iron, and his nails of brass; which devoured, brake in pieces, and stamped the residue with his feet;"},{"ref":"Daniel 7:20","text":"And of the ten horns that were in his head, and of the other which came up, and before whom three fell; even of that horn that had eyes, and a mouth that spake very great things, whose look was more stout than his fellows."},{"ref":"Daniel 7:21","text":"I beheld, and the same horn made war with the saints, and prevailed against them;"},{"ref":"Daniel 7:22","text":"Until the Ancient of days came, and judgment was given to the saints of the most High; and the time came that the saints possessed the kingdom."},{"ref":"Daniel 7:23","text":"Thus he said, The fourth beast shall be the fourth kingdom upon earth, which shall be diverse from all kingdoms, and shall devour the whole earth, and shall tread it down, and break it in pieces."},{"ref":"Daniel 7:24","text":"And the ten horns out of this kingdom are ten kings that shall arise: and another shall rise after them; and he shall be diverse from the first, and he shall subdue three kings."},{"ref":"Daniel 7:25","text":"And he shall speak great words against the most High, and shall wear out the saints of the most High, and think to change times and laws: and they shall be given into his hand until a time and times and the dividing of time."},{"ref":"Daniel 7:26","text":"But the judgment shall sit, and they shall take away his dominion, to consume and to destroy it unto the end."},{"ref":"Daniel 7:27","text":"And the kingdom and dominion, and the greatness of the kingdom under the whole heaven, shall be given to the people of the saints of the most High, whose kingdom is an everlasting kingdom, and all dominions shall serve and obey him."},{"ref":"Daniel 7:28","text":"Hitherto is the end of the matter. As for me Daniel, my cogitations much troubled me, and my countenance changed in me: but I kept the matter in my heart."}],"WEB":[{"ref":"Daniel 7:1","text":"In the first year of Belshazzar king of Babylon Daniel had a dream and visions of his head on his bed. Then he wrote the dream and told the sum of the matters."},{"ref":"Daniel 7:2","text":"Daniel spoke and said, “I saw in my vision by night, and, behold, the four winds of the sky broke out on the great sea."},{"ref":"Daniel 7:3","text":"Four great animals came up from the sea, different from one another."},{"ref":"Daniel 7:4","text":"“The first was like a lion, and had eagle’s wings. I watched until its wings were plucked, and it was lifted up from the earth, and made to stand on two feet as a man. A man’s heart was given to it."},{"ref":"Daniel 7:5","text":"“Behold, there was another animal, a second, like a bear. It was raised up on one side, and three ribs were in its mouth between its teeth. They said this to it: ‘Arise! Devour much flesh!’"},{"ref":"Daniel 7:6","text":"“After this I saw, and behold, another, like a leopard, which had on its back four wings of a bird. The animal also had four heads; and dominion was given to it."},{"ref":"Daniel 7:7","text":"“After this I saw in the night visions, and, behold, there was a fourth animal, awesome and powerful, and exceedingly strong. It had great iron teeth. It devoured and broke in pieces, and stamped the residue with its feet. It was different from all the animals that were before it. It had ten horns."},{"ref":"Daniel 7:8","text":"“I considered the horns, and behold, there came up among them another horn, a little one, before which three of the first horns were plucked up by the roots: and behold, in this horn were eyes like the eyes of a man, and a mouth speaking great things."},{"ref":"Daniel 7:9","text":"“I watched until thrones were placed, and one who was ancient of days sat. His clothing was white as snow, and the hair of his head like pure wool. His throne was fiery flames, and its wheels burning fire."},{"ref":"Daniel 7:10","text":"A fiery stream issued and came out from before him. Thousands of thousands ministered to him. Ten thousand times ten thousand stood before him. The judgment was set. The books were opened."},{"ref":"Daniel 7:11","text":"“I watched at that time because of the voice of the great words which the horn spoke. I watched even until the animal was slain, and its body destroyed, and it was given to be burned with fire."},{"ref":"Daniel 7:12","text":"As for the rest of the animals, their dominion was taken away; yet their lives were prolonged for a season and a time."},{"ref":"Daniel 7:13","text":"“I saw in the night visions, and behold, there came with the clouds of the sky one like a son of man, and he came even to the ancient of days, and they brought him near before him."},{"ref":"Daniel 7:14","text":"Dominion was given him, and glory, and a kingdom, that all the peoples, nations, and languages should serve him. His dominion is an everlasting dominion, which will not pass away, and his kingdom that which will not be destroyed."},{"ref":"Daniel 7:15","text":"“As for me, Daniel, my spirit was grieved within my body, and the visions of my head troubled me."},{"ref":"Daniel 7:16","text":"I came near to one of those who stood by, and asked him the truth concerning all this. “So he told me, and made me know the interpretation of the things."},{"ref":"Daniel 7:17","text":"‘These great animals, which are four, are four kings, who will arise out of the earth."},{"ref":"Daniel 7:18","text":"But the saints of the Most High will receive the kingdom, and possess the kingdom forever, even forever and ever.’"},{"ref":"Daniel 7:19","text":"“Then I desired to know the truth concerning the fourth animal, which was different from all of them, exceedingly terrible, whose teeth were of iron, and its nails of bronze; which devoured, broke in pieces, and stamped the residue with its feet;"},{"ref":"Daniel 7:20","text":"and concerning the ten horns that were on its head, and the other horn which came up, and before which three fell, even that horn that had eyes, and a mouth that spoke great things, whose look was more stout than its fellows."},{"ref":"Daniel 7:21","text":"I saw, and the same horn made war with the saints, and prevailed against them,"},{"ref":"Daniel 7:22","text":"until the ancient of days came, and judgment was given to the saints of the Most High, and the time came that the saints possessed the kingdom."},{"ref":"Daniel 7:23","text":"“Thus he said, ‘The fourth animal will be a fourth kingdom on earth, which will be different from all the kingdoms, and will devour the whole earth, and will tread it down, and break it in pieces."},{"ref":"Daniel 7:24","text":"As for the ten horns, ten kings will arise out of this kingdom. Another will arise after them; and he will be different from the former, and he will put down three kings."},{"ref":"Daniel 7:25","text":"He will speak words against the Most High, and will wear out the saints of the Most High. He will plan to change the times and the law; and they will be given into his hand until a time and times and half a time."},{"ref":"Daniel 7:26","text":"“ ‘But the judgment will be set, and they will take away his dominion, to consume and to destroy it to the end."},{"ref":"Daniel 7:27","text":"The kingdom and the dominion, and the greatness of the kingdoms under the whole sky, will be given to the people of the saints of the Most High. His kingdom is an everlasting kingdom, and all dominions will serve and obey him.’"},{"ref":"Daniel 7:28","text":"“Here is the end of the matter. As for me, Daniel, my thoughts much troubled me, and my face was changed in me; but I kept the matter in my heart.”"}]},"daniel-9":{"BSB":[{"ref":"Daniel 9:24","text":"Seventy weeks are decreed for your people and your holy city to stop their transgression, to put an end to sin, to make atonement for iniquity, to bring in everlasting righteousness, to seal up vision and prophecy, and to anoint the Most Holy Place."},{"ref":"Daniel 9:25","text":"Know and understand this: From the issuance of the decree to restore and rebuild Jerusalem, until the Messiah, the Prince, there will be seven weeks and sixty-two weeks. It will be rebuilt with streets and a trench, but in times of distress."},{"ref":"Daniel 9:26","text":"Then after the sixty-two weeks the Messiah will be cut off and will have nothing. Then the people of the prince who is to come will destroy the city and the sanctuary. The end will come like a flood, and until the end there will be war; desolations have been decreed."},{"ref":"Daniel 9:27","text":"And he will confirm a covenant with many for one week, but in the middle of the week he will put an end to sacrifice and offering. And on the wing of the temple will come the abomination that causes desolation, until the decreed destruction is poured out upon him.”"}],"KJV":[{"ref":"Daniel 9:24","text":"Seventy weeks are determined upon thy people and upon thy holy city, to finish the transgression, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up the vision and prophecy, and to anoint the most Holy."},{"ref":"Daniel 9:25","text":"Know therefore and understand, that from the going forth of the commandment to restore and to build Jerusalem unto the Messiah the Prince shall be seven weeks, and threescore and two weeks: the street shall be built again, and the wall, even in troublous times."},{"ref":"Daniel 9:26","text":"And after threescore and two weeks shall Messiah be cut off, but not for himself: and the people of the prince that shall come shall destroy the city and the sanctuary; and the end thereof shall be with a flood, and unto the end of the war desolations are determined."},{"ref":"Daniel 9:27","text":"And he shall confirm the covenant with many for one week: and in the midst of the week he shall cause the sacrifice and the oblation to cease, and for the overspreading of abominations he shall make it desolate, even until the consummation, and that determined shall be poured upon the desolate."}],"WEB":[{"ref":"Daniel 9:24","text":"“Seventy weeks are decreed on your people and on your holy city, to finish disobedience, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up vision and prophecy, and to anoint the most holy."},{"ref":"Daniel 9:25","text":"“Know therefore and discern that from the going out of the commandment to restore and to build Jerusalem to the Anointed One, the prince, will be seven weeks and sixty-two weeks. It will be built again, with street and moat, even in troubled times."},{"ref":"Daniel 9:26","text":"After the sixty-two weeks the Anointed One will be cut off, and will have nothing. The people of the prince who come will destroy the city and the sanctuary. Its end will be with a flood, and war will be even to the end. Desolations are determined."},{"ref":"Daniel 9:27","text":"He will make a firm covenant with many for one week. In the middle of the week he will cause the sacrifice and the offering to cease. On the wing of abominations will come one who makes desolate; and even to the full end, and that determined, wrath will be poured out on the desolate.”"}]},"2-thessalonians-2":{"BSB":[{"ref":"2 Thessalonians 2:1","text":"Now concerning the coming of our Lord Jesus Christ and our being gathered together to Him, we ask you, brothers,"},{"ref":"2 Thessalonians 2:2","text":"not to be easily disconcerted or alarmed by any spirit or message or letter seeming to be from us, alleging that the Day of the Lord has already come."},{"ref":"2 Thessalonians 2:3","text":"Let no one deceive you in any way, for it will not come until the rebellion occurs and the man of lawlessness—the son of destruction—is revealed."},{"ref":"2 Thessalonians 2:4","text":"He will oppose and exalt himself above every so-called god or object of worship. So he will seat himself in the temple of God, proclaiming himself to be God."},{"ref":"2 Thessalonians 2:5","text":"Do you not remember that I told you these things while I was still with you?"},{"ref":"2 Thessalonians 2:6","text":"And you know what is now restraining him, so that he may be revealed at the proper time."},{"ref":"2 Thessalonians 2:7","text":"For the mystery of lawlessness is already at work, but the one who now restrains it will continue until he is taken out of the way."},{"ref":"2 Thessalonians 2:8","text":"And then the lawless one will be revealed, whom the Lord Jesus will slay with the breath of His mouth and annihilate by the majesty of His arrival."},{"ref":"2 Thessalonians 2:9","text":"The coming of the lawless one will be accompanied by the working of Satan, with every kind of power, sign, and false wonder,"},{"ref":"2 Thessalonians 2:10","text":"and with every wicked deception directed against those who are perishing, because they refused the love of the truth that would have saved them."},{"ref":"2 Thessalonians 2:11","text":"For this reason God will send them a powerful delusion so that they believe the lie,"},{"ref":"2 Thessalonians 2:12","text":"in order that judgment may come upon all who have disbelieved the truth and delighted in wickedness."}],"KJV":[{"ref":"2 Thessalonians 2:1","text":"Now we beseech you, brethren, by the coming of our Lord Jesus Christ, and by our gathering together unto him,"},{"ref":"2 Thessalonians 2:2","text":"That ye be not soon shaken in mind, or be troubled, neither by spirit, nor by word, nor by letter as from us, as that the day of Christ is at hand."},{"ref":"2 Thessalonians 2:3","text":"Let no man deceive you by any means: for that day shall not come, except there come a falling away first, and that man of sin be revealed, the son of perdition;"},{"ref":"2 Thessalonians 2:4","text":"Who opposeth and exalteth himself above all that is called God, or that is worshipped; so that he as God sitteth in the temple of God, shewing himself that he is God."},{"ref":"2 Thessalonians 2:5","text":"Remember ye not, that, when I was yet with you, I told you these things?"},{"ref":"2 Thessalonians 2:6","text":"And now ye know what withholdeth that he might be revealed in his time."},{"ref":"2 Thessalonians 2:7","text":"For the mystery of iniquity doth already work: only he who now letteth will let, until he be taken out of the way."},{"ref":"2 Thessalonians 2:8","text":"And then shall that Wicked be revealed, whom the Lord shall consume with the spirit of his mouth, and shall destroy with the brightness of his coming:"},{"ref":"2 Thessalonians 2:9","text":"Even him, whose coming is after the working of Satan with all power and signs and lying wonders,"},{"ref":"2 Thessalonians 2:10","text":"And with all deceivableness of unrighteousness in them that perish; because they received not the love of the truth, that they might be saved."},{"ref":"2 Thessalonians 2:11","text":"And for this cause God shall send them strong delusion, that they should believe a lie:"},{"ref":"2 Thessalonians 2:12","text":"That they all might be damned who believed not the truth, but had pleasure in unrighteousness."}],"WEB":[{"ref":"2 Thessalonians 2:1","text":"Now, brothers, concerning the coming of our Lord Jesus Christ and our gathering together to him, we ask you"},{"ref":"2 Thessalonians 2:2","text":"not to be quickly shaken in your mind, and not be troubled, either by spirit, or by word, or by letter as if from us, saying that the day of Christ has already come."},{"ref":"2 Thessalonians 2:3","text":"Let no one deceive you in any way. For it will not be, unless the rebellion comes first, and the man of sin is revealed, the son of destruction,"},{"ref":"2 Thessalonians 2:4","text":"he who opposes and exalts himself against all that is called God or that is worshiped, so that he sits as God in the temple of God, setting himself up as God."},{"ref":"2 Thessalonians 2:5","text":"Don’t you remember that, when I was still with you, I told you these things?"},{"ref":"2 Thessalonians 2:6","text":"Now you know what is restraining him, to the end that he may be revealed in his own season."},{"ref":"2 Thessalonians 2:7","text":"For the mystery of lawlessness already works. Only there is one who restrains now, until he is taken out of the way."},{"ref":"2 Thessalonians 2:8","text":"Then the lawless one will be revealed, whom the Lord will kill with the breath of his mouth, and destroy by the manifestation of his coming;"},{"ref":"2 Thessalonians 2:9","text":"even he whose coming is according to the working of Satan with all power and signs and lying wonders,"},{"ref":"2 Thessalonians 2:10","text":"and with all deception of wickedness for those who are being lost, because they didn’t receive the love of the truth, that they might be saved."},{"ref":"2 Thessalonians 2:11","text":"Because of this, God sends them a working of error, that they should believe a lie;"},{"ref":"2 Thessalonians 2:12","text":"that they all might be judged who didn’t believe the truth, but had pleasure in unrighteousness."}]},"1-thessalonians-4-5":{"BSB":[{"ref":"1 Thessalonians 4:13","text":"Brothers, we do not want you to be uninformed about those who sleep in death, so that you will not grieve like the rest, who are without hope."},{"ref":"1 Thessalonians 4:14","text":"For since we believe that Jesus died and rose again, we also believe that God will bring with Jesus those who have fallen asleep in Him."},{"ref":"1 Thessalonians 4:15","text":"By the word of the Lord, we declare to you that we who are alive and remain until the coming of the Lord will by no means precede those who have fallen asleep."},{"ref":"1 Thessalonians 4:16","text":"For the Lord Himself will descend from heaven with a loud command, with the voice of an archangel, and with the trumpet of God, and the dead in Christ will be the first to rise."},{"ref":"1 Thessalonians 4:17","text":"After that, we who are alive and remain will be caught up together with them in the clouds to meet the Lord in the air. And so we will always be with the Lord."},{"ref":"1 Thessalonians 4:18","text":"Therefore encourage one another with these words."},{"ref":"1 Thessalonians 5:1","text":"Now about the times and seasons, brothers, we do not need to write to you."},{"ref":"1 Thessalonians 5:2","text":"For you are fully aware that the Day of the Lord will come like a thief in the night."},{"ref":"1 Thessalonians 5:3","text":"While people are saying, “Peace and security,” destruction will come upon them suddenly, like labor pains on a pregnant woman, and they will not escape."},{"ref":"1 Thessalonians 5:4","text":"But you, brothers, are not in the darkness so that this day should overtake you like a thief."},{"ref":"1 Thessalonians 5:5","text":"For you are all sons of the light and sons of the day; we do not belong to the night or to the darkness."},{"ref":"1 Thessalonians 5:6","text":"So then, let us not sleep as the others do, but let us remain awake and sober."},{"ref":"1 Thessalonians 5:7","text":"For those who sleep, sleep at night; and those who get drunk, get drunk at night."},{"ref":"1 Thessalonians 5:8","text":"But since we belong to the day, let us be sober, putting on the breastplate of faith and love, and the helmet of our hope of salvation."},{"ref":"1 Thessalonians 5:9","text":"For God has not appointed us to suffer wrath, but to obtain salvation through our Lord Jesus Christ."},{"ref":"1 Thessalonians 5:10","text":"He died for us so that, whether we are awake or asleep, we may live together with Him."},{"ref":"1 Thessalonians 5:11","text":"Therefore encourage and build one another up, just as you are already doing."}],"KJV":[{"ref":"1 Thessalonians 4:13","text":"But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope."},{"ref":"1 Thessalonians 4:14","text":"For if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him."},{"ref":"1 Thessalonians 4:15","text":"For this we say unto you by the word of the Lord, that we which are alive and remain unto the coming of the Lord shall not prevent them which are asleep."},{"ref":"1 Thessalonians 4:16","text":"For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:"},{"ref":"1 Thessalonians 4:17","text":"Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord."},{"ref":"1 Thessalonians 4:18","text":"Wherefore comfort one another with these words."},{"ref":"1 Thessalonians 5:1","text":"But of the times and the seasons, brethren, ye have no need that I write unto you."},{"ref":"1 Thessalonians 5:2","text":"For yourselves know perfectly that the day of the Lord so cometh as a thief in the night."},{"ref":"1 Thessalonians 5:3","text":"For when they shall say, Peace and safety; then sudden destruction cometh upon them, as travail upon a woman with child; and they shall not escape."},{"ref":"1 Thessalonians 5:4","text":"But ye, brethren, are not in darkness, that that day should overtake you as a thief."},{"ref":"1 Thessalonians 5:5","text":"Ye are all the children of light, and the children of the day: we are not of the night, nor of darkness."},{"ref":"1 Thessalonians 5:6","text":"Therefore let us not sleep, as do others; but let us watch and be sober."},{"ref":"1 Thessalonians 5:7","text":"For they that sleep sleep in the night; and they that be drunken are drunken in the night."},{"ref":"1 Thessalonians 5:8","text":"But let us, who are of the day, be sober, putting on the breastplate of faith and love; and for an helmet, the hope of salvation."},{"ref":"1 Thessalonians 5:9","text":"For God hath not appointed us to wrath, but to obtain salvation by our Lord Jesus Christ,"},{"ref":"1 Thessalonians 5:10","text":"Who died for us, that, whether we wake or sleep, we should live together with him."},{"ref":"1 Thessalonians 5:11","text":"Wherefore comfort yourselves together, and edify one another, even as also ye do."}],"WEB":[{"ref":"1 Thessalonians 4:13","text":"But we don’t want you to be ignorant, brothers, concerning those who have fallen asleep, so that you don’t grieve like the rest, who have no hope."},{"ref":"1 Thessalonians 4:14","text":"For if we believe that Jesus died and rose again, even so God will bring with him those who have fallen asleep in Jesus."},{"ref":"1 Thessalonians 4:15","text":"For this we tell you by the word of the Lord, that we who are alive, who are left until the coming of the Lord, will in no way precede those who have fallen asleep."},{"ref":"1 Thessalonians 4:16","text":"For the Lord himself will descend from heaven with a shout, with the voice of the archangel and with God’s trumpet. The dead in Christ will rise first,"},{"ref":"1 Thessalonians 4:17","text":"then we who are alive, who are left, will be caught up together with them in the clouds, to meet the Lord in the air. So we will be with the Lord forever."},{"ref":"1 Thessalonians 4:18","text":"Therefore comfort one another with these words."},{"ref":"1 Thessalonians 5:1","text":"But concerning the times and the seasons, brothers, you have no need that anything be written to you."},{"ref":"1 Thessalonians 5:2","text":"For you yourselves know well that the day of the Lord comes like a thief in the night."},{"ref":"1 Thessalonians 5:3","text":"For when they are saying, “Peace and safety,” then sudden destruction will come on them, like birth pains on a pregnant woman. Then they will in no way escape."},{"ref":"1 Thessalonians 5:4","text":"But you, brothers, aren’t in darkness, that the day should overtake you like a thief."},{"ref":"1 Thessalonians 5:5","text":"You are all children of light and children of the day. We don’t belong to the night, nor to darkness,"},{"ref":"1 Thessalonians 5:6","text":"so then let’s not sleep, as the rest do, but let’s watch and be sober."},{"ref":"1 Thessalonians 5:7","text":"For those who sleep, sleep in the night; and those who are drunk are drunk in the night."},{"ref":"1 Thessalonians 5:8","text":"But since we belong to the day, let’s be sober, putting on the breastplate of faith and love, and for a helmet, the hope of salvation."},{"ref":"1 Thessalonians 5:9","text":"For God didn’t appoint us to wrath, but to the obtaining of salvation through our Lord Jesus Christ,"},{"ref":"1 Thessalonians 5:10","text":"who died for us, that, whether we wake or sleep, we should live together with him."},{"ref":"1 Thessalonians 5:11","text":"Therefore exhort one another, and build each other up, even as you also do."}]},"1-corinthians-15-20-28":{"BSB":[{"ref":"1 Corinthians 15:20","text":"But Christ has indeed been raised from the dead, the firstfruits of those who have fallen asleep."},{"ref":"1 Corinthians 15:21","text":"For since death came through a man, the resurrection of the dead comes also through a man."},{"ref":"1 Corinthians 15:22","text":"For as in Adam all die, so in Christ all will be made alive."},{"ref":"1 Corinthians 15:23","text":"But each in his own turn: Christ the firstfruits; then at His coming, those who belong to Him."},{"ref":"1 Corinthians 15:24","text":"Then the end will come, when He hands over the kingdom to God the Father after He has destroyed all dominion, authority, and power."},{"ref":"1 Corinthians 15:25","text":"For He must reign until He has put all His enemies under His feet."},{"ref":"1 Corinthians 15:26","text":"The last enemy to be destroyed is death."},{"ref":"1 Corinthians 15:27","text":"For “God has put everything under His feet.” Now when it says that everything has been put under Him, this clearly does not include the One who put everything under Him."},{"ref":"1 Corinthians 15:28","text":"And when all things have been subjected to Him, then the Son Himself will be made subject to Him who put all things under Him, so that God may be all in all."}],"KJV":[{"ref":"1 Corinthians 15:20","text":"But now is Christ risen from the dead, and become the firstfruits of them that slept."},{"ref":"1 Corinthians 15:21","text":"For since by man came death, by man came also the resurrection of the dead."},{"ref":"1 Corinthians 15:22","text":"For as in Adam all die, even so in Christ shall all be made alive."},{"ref":"1 Corinthians 15:23","text":"But every man in his own order: Christ the firstfruits; afterward they that are Christ's at his coming."},{"ref":"1 Corinthians 15:24","text":"Then cometh the end, when he shall have delivered up the kingdom to God, even the Father; when he shall have put down all rule and all authority and power."},{"ref":"1 Corinthians 15:25","text":"For he must reign, till he hath put all enemies under his feet."},{"ref":"1 Corinthians 15:26","text":"The last enemy that shall be destroyed is death."},{"ref":"1 Corinthians 15:27","text":"For he hath put all things under his feet. But when he saith all things are put under him, it is manifest that he is excepted, which did put all things under him."},{"ref":"1 Corinthians 15:28","text":"And when all things shall be subdued unto him, then shall the Son also himself be subject unto him that put all things under him, that God may be all in all."}],"WEB":[{"ref":"1 Corinthians 15:20","text":"But now Christ has been raised from the dead. He became the first fruits of those who are asleep."},{"ref":"1 Corinthians 15:21","text":"For since death came by man, the resurrection of the dead also came by man."},{"ref":"1 Corinthians 15:22","text":"For as in Adam all die, so also in Christ all will be made alive."},{"ref":"1 Corinthians 15:23","text":"But each in his own order: Christ the first fruits, then those who are Christ’s, at his coming."},{"ref":"1 Corinthians 15:24","text":"Then the end comes, when he will deliver up the Kingdom to God, even the Father, when he will have abolished all rule and all authority and power."},{"ref":"1 Corinthians 15:25","text":"For he must reign until he has put all his enemies under his feet."},{"ref":"1 Corinthians 15:26","text":"The last enemy that will be abolished is death."},{"ref":"1 Corinthians 15:27","text":"For, “He put all things in subjection under his feet.” But when he says, “All things are put in subjection”, it is evident that he is excepted who subjected all things to him."},{"ref":"1 Corinthians 15:28","text":"When all things have been subjected to him, then the Son will also himself be subjected to him who subjected all things to him, that God may be all in all."}]},"romans-11":{"BSB":[{"ref":"Romans 11:11","text":"I ask then, did they stumble so as to fall beyond recovery? Certainly not! However, because of their trespass, salvation has come to the Gentiles to make Israel jealous."},{"ref":"Romans 11:12","text":"But if their trespass means riches for the world, and their failure means riches for the Gentiles, how much greater riches will their fullness bring!"},{"ref":"Romans 11:13","text":"I am speaking to you Gentiles. Inasmuch as I am the apostle to the Gentiles, I magnify my ministry"},{"ref":"Romans 11:14","text":"in the hope that I may provoke my own people to jealousy and save some of them."},{"ref":"Romans 11:15","text":"For if their rejection is the reconciliation of the world, what will their acceptance be but life from the dead?"},{"ref":"Romans 11:16","text":"If the first part of the dough is holy, so is the whole batch; if the root is holy, so are the branches."},{"ref":"Romans 11:17","text":"Now if some branches have been broken off, and you, a wild olive shoot, have been grafted in among the others to share in the nourishment of the olive root,"},{"ref":"Romans 11:18","text":"do not boast over those branches. If you do, remember this: You do not support the root, but the root supports you."},{"ref":"Romans 11:19","text":"You will say then, “Branches were broken off so that I could be grafted in.”"},{"ref":"Romans 11:20","text":"That is correct: They were broken off because of unbelief, but you stand by faith. Do not be arrogant, but be afraid."},{"ref":"Romans 11:21","text":"For if God did not spare the natural branches, He will certainly not spare you either."},{"ref":"Romans 11:22","text":"Take notice, therefore, of the kindness and severity of God: severity to those who fell, but kindness to you, if you continue in His kindness. Otherwise you also will be cut off."},{"ref":"Romans 11:23","text":"And if they do not persist in unbelief, they will be grafted in, for God is able to graft them in again."},{"ref":"Romans 11:24","text":"For if you were cut from a wild olive tree, and contrary to nature were grafted into one that is cultivated, how much more readily will these, the natural branches, be grafted into their own olive tree!"},{"ref":"Romans 11:25","text":"I do not want you to be ignorant of this mystery, brothers, so that you will not be conceited: A hardening in part has come to Israel, until the full number of the Gentiles has come in."},{"ref":"Romans 11:26","text":"And so all Israel will be saved, as it is written: “The Deliverer will come from Zion; He will remove godlessness from Jacob."},{"ref":"Romans 11:27","text":"And this is My covenant with them when I take away their sins.”"},{"ref":"Romans 11:28","text":"Regarding the gospel, they are enemies on your account; but regarding election, they are loved on account of the patriarchs."},{"ref":"Romans 11:29","text":"For God’s gifts and His call are irrevocable."},{"ref":"Romans 11:30","text":"Just as you who formerly disobeyed God have now received mercy through their disobedience,"},{"ref":"Romans 11:31","text":"so they too have now disobeyed, in order that they too may now receive mercy through the mercy shown to you."},{"ref":"Romans 11:32","text":"For God has consigned everyone to disobedience so that He may have mercy on everyone."}],"KJV":[{"ref":"Romans 11:11","text":"I say then, Have they stumbled that they should fall? God forbid: but rather through their fall salvation is come unto the Gentiles, for to provoke them to jealousy."},{"ref":"Romans 11:12","text":"Now if the fall of them be the riches of the world, and the diminishing of them the riches of the Gentiles; how much more their fulness?"},{"ref":"Romans 11:13","text":"For I speak to you Gentiles, inasmuch as I am the apostle of the Gentiles, I magnify mine office:"},{"ref":"Romans 11:14","text":"If by any means I may provoke to emulation them which are my flesh, and might save some of them."},{"ref":"Romans 11:15","text":"For if the casting away of them be the reconciling of the world, what shall the receiving of them be, but life from the dead?"},{"ref":"Romans 11:16","text":"For if the firstfruit be holy, the lump is also holy: and if the root be holy, so are the branches."},{"ref":"Romans 11:17","text":"And if some of the branches be broken off, and thou, being a wild olive tree, wert graffed in among them, and with them partakest of the root and fatness of the olive tree;"},{"ref":"Romans 11:18","text":"Boast not against the branches. But if thou boast, thou bearest not the root, but the root thee."},{"ref":"Romans 11:19","text":"Thou wilt say then, The branches were broken off, that I might be graffed in."},{"ref":"Romans 11:20","text":"Well; because of unbelief they were broken off, and thou standest by faith. Be not highminded, but fear:"},{"ref":"Romans 11:21","text":"For if God spared not the natural branches, take heed lest he also spare not thee."},{"ref":"Romans 11:22","text":"Behold therefore the goodness and severity of God: on them which fell, severity; but toward thee, goodness, if thou continue in his goodness: otherwise thou also shalt be cut off."},{"ref":"Romans 11:23","text":"And they also, if they abide not still in unbelief, shall be graffed in: for God is able to graff them in again."},{"ref":"Romans 11:24","text":"For if thou wert cut out of the olive tree which is wild by nature, and wert graffed contrary to nature into a good olive tree: how much more shall these, which be the natural branches, be graffed into their own olive tree?"},{"ref":"Romans 11:25","text":"For I would not, brethren, that ye should be ignorant of this mystery, lest ye should be wise in your own conceits; that blindness in part is happened to Israel, until the fulness of the Gentiles be come in."},{"ref":"Romans 11:26","text":"And so all Israel shall be saved: as it is written, There shall come out of Sion the Deliverer, and shall turn away ungodliness from Jacob:"},{"ref":"Romans 11:27","text":"For this is my covenant unto them, when I shall take away their sins."},{"ref":"Romans 11:28","text":"As concerning the gospel, they are enemies for your sakes: but as touching the election, they are beloved for the fathers' sakes."},{"ref":"Romans 11:29","text":"For the gifts and calling of God are without repentance."},{"ref":"Romans 11:30","text":"For as ye in times past have not believed God, yet have now obtained mercy through their unbelief:"},{"ref":"Romans 11:31","text":"Even so have these also now not believed, that through your mercy they also may obtain mercy."},{"ref":"Romans 11:32","text":"For God hath concluded them all in unbelief, that he might have mercy upon all."}],"WEB":[{"ref":"Romans 11:11","text":"I ask then, did they stumble that they might fall? May it never be! But by their fall salvation has come to the Gentiles, to provoke them to jealousy."},{"ref":"Romans 11:12","text":"Now if their fall is the riches of the world, and their loss the riches of the Gentiles; how much more their fullness?"},{"ref":"Romans 11:13","text":"For I speak to you who are Gentiles. Since then as I am an apostle to Gentiles, I glorify my ministry;"},{"ref":"Romans 11:14","text":"if by any means I may provoke to jealousy those who are my flesh, and may save some of them."},{"ref":"Romans 11:15","text":"For if the rejection of them is the reconciling of the world, what would their acceptance be, but life from the dead?"},{"ref":"Romans 11:16","text":"If the first fruit is holy, so is the lump. If the root is holy, so are the branches."},{"ref":"Romans 11:17","text":"But if some of the branches were broken off, and you, being a wild olive, were grafted in among them and became partaker with them of the root and of the richness of the olive tree,"},{"ref":"Romans 11:18","text":"don’t boast over the branches. But if you boast, it is not you who support the root, but the root supports you."},{"ref":"Romans 11:19","text":"You will say then, “Branches were broken off, that I might be grafted in.”"},{"ref":"Romans 11:20","text":"True; by their unbelief they were broken off, and you stand by your faith. Don’t be conceited, but fear;"},{"ref":"Romans 11:21","text":"for if God didn’t spare the natural branches, neither will he spare you."},{"ref":"Romans 11:22","text":"See then the goodness and severity of God. Toward those who fell, severity; but toward you, goodness, if you continue in his goodness; otherwise you also will be cut off."},{"ref":"Romans 11:23","text":"They also, if they don’t continue in their unbelief, will be grafted in, for God is able to graft them in again."},{"ref":"Romans 11:24","text":"For if you were cut out of that which is by nature a wild olive tree, and were grafted contrary to nature into a good olive tree, how much more will these, which are the natural branches, be grafted into their own olive tree?"},{"ref":"Romans 11:25","text":"For I don’t desire you to be ignorant, brothers, of this mystery, so that you won’t be wise in your own conceits, that a partial hardening has happened to Israel, until the fullness of the Gentiles has come in,"},{"ref":"Romans 11:26","text":"and so all Israel will be saved. Even as it is written, “There will come out of Zion the Deliverer, and he will turn away ungodliness from Jacob."},{"ref":"Romans 11:27","text":"This is my covenant with them, when I will take away their sins.”"},{"ref":"Romans 11:28","text":"Concerning the Good News, they are enemies for your sake. But concerning the election, they are beloved for the fathers’ sake."},{"ref":"Romans 11:29","text":"For the gifts and the calling of God are irrevocable."},{"ref":"Romans 11:30","text":"For as you in time past were disobedient to God, but now have obtained mercy by their disobedience,"},{"ref":"Romans 11:31","text":"even so these also have now been disobedient, that by the mercy shown to you they may also obtain mercy."},{"ref":"Romans 11:32","text":"For God has bound all to disobedience, that he might have mercy on all."}]},"psalm-2":{"BSB":[{"ref":"Psalms 2:1","text":"Why do the nations rage and the peoples plot in vain?"},{"ref":"Psalms 2:2","text":"The kings of the earth take their stand and the rulers gather together, against the LORD and against His Anointed One:"},{"ref":"Psalms 2:3","text":"“Let us break Their chains and cast away Their cords.”"},{"ref":"Psalms 2:4","text":"The One enthroned in heaven laughs; the Lord taunts them."},{"ref":"Psalms 2:5","text":"Then He rebukes them in His anger, and terrifies them in His fury:"},{"ref":"Psalms 2:6","text":"“I have installed My King on Zion, upon My holy mountain.”"},{"ref":"Psalms 2:7","text":"I will proclaim the decree spoken to Me by the LORD: “You are My Son; today I have become Your Father."},{"ref":"Psalms 2:8","text":"Ask Me, and I will make the nations Your inheritance, the ends of the earth Your possession."},{"ref":"Psalms 2:9","text":"You will break them with an iron scepter; You will shatter them like pottery.”"},{"ref":"Psalms 2:10","text":"Therefore be wise, O kings; be admonished, O judges of the earth."},{"ref":"Psalms 2:11","text":"Serve the LORD with fear, and rejoice with trembling."},{"ref":"Psalms 2:12","text":"Kiss the Son, lest He be angry and you perish in your rebellion, when His wrath ignites in an instant. Blessed are all who take refuge in Him."}],"KJV":[{"ref":"Psalms 2:1","text":"Why do the heathen rage, and the people imagine a vain thing?"},{"ref":"Psalms 2:2","text":"The kings of the earth set themselves, and the rulers take counsel together, against the LORD, and against his anointed, saying,"},{"ref":"Psalms 2:3","text":"Let us break their bands asunder, and cast away their cords from us."},{"ref":"Psalms 2:4","text":"He that sitteth in the heavens shall laugh: the Lord shall have them in derision."},{"ref":"Psalms 2:5","text":"Then shall he speak unto them in his wrath, and vex them in his sore displeasure."},{"ref":"Psalms 2:6","text":"Yet have I set my king upon my holy hill of Zion."},{"ref":"Psalms 2:7","text":"I will declare the decree: the LORD hath said unto me, Thou art my Son; this day have I begotten thee."},{"ref":"Psalms 2:8","text":"Ask of me, and I shall give thee the heathen for thine inheritance, and the uttermost parts of the earth for thy possession."},{"ref":"Psalms 2:9","text":"Thou shalt break them with a rod of iron; thou shalt dash them in pieces like a potter's vessel."},{"ref":"Psalms 2:10","text":"Be wise now therefore, O ye kings: be instructed, ye judges of the earth."},{"ref":"Psalms 2:11","text":"Serve the LORD with fear, and rejoice with trembling."},{"ref":"Psalms 2:12","text":"Kiss the Son, lest he be angry, and ye perish from the way, when his wrath is kindled but a little. Blessed are all they that put their trust in him."}],"WEB":[{"ref":"Psalms 2:1","text":"Why do the nations rage, and the peoples plot a vain thing?"},{"ref":"Psalms 2:2","text":"The kings of the earth take a stand, and the rulers take counsel together, against Yahweh, and against his Anointed, saying,"},{"ref":"Psalms 2:3","text":"“Let’s break their bonds apart, and cast their cords from us.”"},{"ref":"Psalms 2:4","text":"He who sits in the heavens will laugh. The Lord will have them in derision."},{"ref":"Psalms 2:5","text":"Then he will speak to them in his anger, and terrify them in his wrath:"},{"ref":"Psalms 2:6","text":"“Yet I have set my King on my holy hill of Zion.”"},{"ref":"Psalms 2:7","text":"I will tell of the decree: Yahweh said to me, “You are my son. Today I have become your father."},{"ref":"Psalms 2:8","text":"Ask of me, and I will give the nations for your inheritance, the uttermost parts of the earth for your possession."},{"ref":"Psalms 2:9","text":"You shall break them with a rod of iron. You shall dash them in pieces like a potter’s vessel.”"},{"ref":"Psalms 2:10","text":"Now therefore be wise, you kings. Be instructed, you judges of the earth."},{"ref":"Psalms 2:11","text":"Serve Yahweh with fear, and rejoice with trembling."},{"ref":"Psalms 2:12","text":"Give sincere homage to the Son, lest he be angry, and you perish on the way, for his wrath will soon be kindled. Blessed are all those who take refuge in him."}]},"psalm-110":{"BSB":[{"ref":"Psalms 110:1","text":"A Psalm of David. The LORD said to my Lord: “Sit at My right hand until I make Your enemies a footstool for Your feet.”"},{"ref":"Psalms 110:2","text":"The LORD extends Your mighty scepter from Zion: “Rule in the midst of Your enemies.”"},{"ref":"Psalms 110:3","text":"Your people shall be willing on Your day of battle. Arrayed in holy splendor, from the womb of the dawn, to You belongs the dew of Your youth."},{"ref":"Psalms 110:4","text":"The LORD has sworn and will not change His mind: “You are a priest forever in the order of Melchizedek.”"},{"ref":"Psalms 110:5","text":"The Lord is at Your right hand; He will crush kings in the day of His wrath."},{"ref":"Psalms 110:6","text":"He will judge the nations, heaping up the dead; He will crush the leaders far and wide."},{"ref":"Psalms 110:7","text":"He will drink from the brook by the road; therefore He will lift up His head."}],"KJV":[{"ref":"Psalms 110:1","text":"The LORD said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool."},{"ref":"Psalms 110:2","text":"The LORD shall send the rod of thy strength out of Zion: rule thou in the midst of thine enemies."},{"ref":"Psalms 110:3","text":"Thy people shall be willing in the day of thy power, in the beauties of holiness from the womb of the morning: thou hast the dew of thy youth."},{"ref":"Psalms 110:4","text":"The LORD hath sworn, and will not repent, Thou art a priest for ever after the order of Melchizedek."},{"ref":"Psalms 110:5","text":"The Lord at thy right hand shall strike through kings in the day of his wrath."},{"ref":"Psalms 110:6","text":"He shall judge among the heathen, he shall fill the places with the dead bodies; he shall wound the heads over many countries."},{"ref":"Psalms 110:7","text":"He shall drink of the brook in the way: therefore shall he lift up the head."}],"WEB":[{"ref":"Psalms 110:1","text":"Yahweh says to my Lord, “Sit at my right hand, until I make your enemies your footstool for your feet.”"},{"ref":"Psalms 110:2","text":"Yahweh will send out the rod of your strength out of Zion. Rule among your enemies."},{"ref":"Psalms 110:3","text":"Your people offer themselves willingly in the day of your power, in holy array. Out of the womb of the morning, you have the dew of your youth."},{"ref":"Psalms 110:4","text":"Yahweh has sworn, and will not change his mind: “You are a priest forever in the order of Melchizedek.”"},{"ref":"Psalms 110:5","text":"The Lord is at your right hand. He will crush kings in the day of his wrath."},{"ref":"Psalms 110:6","text":"He will judge among the nations. He will heap up dead bodies. He will crush the ruler of the whole earth."},{"ref":"Psalms 110:7","text":"He will drink of the brook on the way; therefore he will lift up his head."}]},"isaiah-2":{"BSB":[{"ref":"Isaiah 2:2","text":"In the last days the mountain of the house of the LORD will be established as the chief of the mountains; it will be raised above the hills, and all nations will stream to it."},{"ref":"Isaiah 2:3","text":"And many peoples will come and say: “Come, let us go up to the mountain of the LORD, to the house of the God of Jacob. He will teach us His ways so that we may walk in His paths.” For the law will go forth from Zion, and the word of the LORD from Jerusalem."},{"ref":"Isaiah 2:4","text":"Then He will judge between the nations and arbitrate for many peoples. They will beat their swords into plowshares and their spears into pruning hooks. Nation will no longer take up the sword against nation, nor train anymore for war."}],"KJV":[{"ref":"Isaiah 2:2","text":"And it shall come to pass in the last days, that the mountain of the LORD'S house shall be established in the top of the mountains, and shall be exalted above the hills; and all nations shall flow unto it."},{"ref":"Isaiah 2:3","text":"And many people shall go and say, Come ye, and let us go up to the mountain of the LORD, to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths: for out of Zion shall go forth the law, and the word of the LORD from Jerusalem."},{"ref":"Isaiah 2:4","text":"And he shall judge among the nations, and shall rebuke many people: and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more."}],"WEB":[{"ref":"Isaiah 2:2","text":"It shall happen in the latter days, that the mountain of Yahweh’s house shall be established on the top of the mountains, and shall be raised above the hills; and all nations shall flow to it."},{"ref":"Isaiah 2:3","text":"Many peoples shall go and say, “Come, let’s go up to the mountain of Yahweh, to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths.” For the law shall go out of Zion, and Yahweh’s word from Jerusalem."},{"ref":"Isaiah 2:4","text":"He will judge between the nations, and will decide concerning many peoples. They shall beat their swords into plowshares, and their spears into pruning hooks. Nation shall not lift up sword against nation, neither shall they learn war any more."}]},"isaiah-9":{"BSB":[{"ref":"Isaiah 9:6","text":"For unto us a child is born, unto us a son is given, and the government will be upon His shoulders. And He will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace."},{"ref":"Isaiah 9:7","text":"Of the increase of His government and peace there will be no end. He will reign on the throne of David and over his kingdom, to establish and sustain it with justice and righteousness from that time and forevermore. The zeal of the LORD of Hosts will accomplish this."}],"KJV":[{"ref":"Isaiah 9:6","text":"For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace."},{"ref":"Isaiah 9:7","text":"Of the increase of his government and peace there shall be no end, upon the throne of David, and upon his kingdom, to order it, and to establish it with judgment and with justice from henceforth even for ever. The zeal of the LORD of hosts will perform this."}],"WEB":[{"ref":"Isaiah 9:6","text":"For a child is born to us. A son is given to us; and the government will be on his shoulders. His name will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace."},{"ref":"Isaiah 9:7","text":"Of the increase of his government and of peace there shall be no end, on David’s throne, and on his kingdom, to establish it, and to uphold it with justice and with righteousness from that time on, even forever. The zeal of Yahweh of Armies will perform this."}]},"isaiah-65":{"BSB":[{"ref":"Isaiah 65:17","text":"For behold, I will create new heavens and a new earth. The former things will not be remembered, nor will they come to mind."},{"ref":"Isaiah 65:18","text":"But be glad and rejoice forever in what I create; for I will create Jerusalem to be a joy and its people to be a delight."},{"ref":"Isaiah 65:19","text":"I will rejoice in Jerusalem and take delight in My people. The sounds of weeping and crying will no longer be heard in her."},{"ref":"Isaiah 65:20","text":"No longer will a nursing infant live but a few days, or an old man fail to live out his years. For the youth will die at a hundred years, and he who fails to reach a hundred will be considered accursed."},{"ref":"Isaiah 65:21","text":"They will build houses and dwell in them; they will plant vineyards and eat their fruit."},{"ref":"Isaiah 65:22","text":"No longer will they build houses for others to inhabit, nor plant for others to eat. For as is the lifetime of a tree, so will be the days of My people, and My chosen ones will fully enjoy the work of their hands."},{"ref":"Isaiah 65:23","text":"They will not labor in vain or bear children doomed to disaster; for they will be a people blessed by the LORD—they and their descendants with them."},{"ref":"Isaiah 65:24","text":"Even before they call, I will answer, and while they are still speaking, I will hear."},{"ref":"Isaiah 65:25","text":"The wolf and the lamb will feed together, and the lion will eat straw like the ox, but the food of the serpent will be dust. They will neither harm nor destroy on all My holy mountain,” says the LORD."}],"KJV":[{"ref":"Isaiah 65:17","text":"# For, behold, I create new heavens and a new earth: and the former shall not be remembered, nor come into mind."},{"ref":"Isaiah 65:18","text":"But be ye glad and rejoice for ever in that which I create: for, behold, I create Jerusalem a rejoicing, and her people a joy."},{"ref":"Isaiah 65:19","text":"And I will rejoice in Jerusalem, and joy in my people: and the voice of weeping shall be no more heard in her, nor the voice of crying."},{"ref":"Isaiah 65:20","text":"There shall be no more thence an infant of days, nor an old man that hath not filled his days: for the child shall die an hundred years old; but the sinner being an hundred years old shall be accursed."},{"ref":"Isaiah 65:21","text":"And they shall build houses, and inhabit them; and they shall plant vineyards, and eat the fruit of them."},{"ref":"Isaiah 65:22","text":"They shall not build, and another inhabit; they shall not plant, and another eat: for as the days of a tree are the days of my people, and mine elect shall long enjoy the work of their hands."},{"ref":"Isaiah 65:23","text":"They shall not labour in vain, nor bring forth for trouble; for they are the seed of the blessed of the LORD, and their offspring with them."},{"ref":"Isaiah 65:24","text":"And it shall come to pass, that before they call, I will answer; and while they are yet speaking, I will hear."},{"ref":"Isaiah 65:25","text":"The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock: and dust shall be the serpent's meat. They shall not hurt nor destroy in all my holy mountain, saith the LORD."}],"WEB":[{"ref":"Isaiah 65:17","text":"“For, behold, I create new heavens and a new earth; and the former things will not be remembered, nor come into mind."},{"ref":"Isaiah 65:18","text":"But be glad and rejoice forever in that which I create; for, behold, I create Jerusalem to be a delight, and her people a joy."},{"ref":"Isaiah 65:19","text":"I will rejoice in Jerusalem, and delight in my people; and the voice of weeping and the voice of crying will be heard in her no more."},{"ref":"Isaiah 65:20","text":"“No more will there be an infant who only lives a few days, nor an old man who has not filled his days; for the child will die one hundred years old, and the sinner being one hundred years old will be accursed."},{"ref":"Isaiah 65:21","text":"They will build houses and inhabit them. They will plant vineyards and eat their fruit."},{"ref":"Isaiah 65:22","text":"They will not build and another inhabit. They will not plant and another eat: for the days of my people will be like the days of a tree, and my chosen will long enjoy the work of their hands."},{"ref":"Isaiah 65:23","text":"They will not labor in vain nor give birth for calamity; for they are the offspring of Yahweh’s blessed and their descendants with them."},{"ref":"Isaiah 65:24","text":"It will happen that before they call, I will answer; and while they are yet speaking, I will hear."},{"ref":"Isaiah 65:25","text":"The wolf and the lamb will feed together. The lion will eat straw like the ox. Dust will be the serpent’s food. They will not hurt nor destroy in all my holy mountain,” says Yahweh."}]},"ezekiel-37-one-nation-one-shepherd":{"BSB":[{"ref":"Ezekiel 37:21","text":"you are to tell them that this is what the Lord GOD says: ‘I will take the Israelites out of the nations to which they have gone, and I will gather them from all around and bring them into their own land."},{"ref":"Ezekiel 37:22","text":"I will make them one nation in the land, on the mountains of Israel, and one king will rule over all of them. Then they will no longer be two nations and will never again be divided into two kingdoms."},{"ref":"Ezekiel 37:23","text":"They will no longer defile themselves with their idols or detestable images, or with any of their transgressions. I will save them from all their apostasies by which they sinned, and I will cleanse them. Then they will be My people, and I will be their God."},{"ref":"Ezekiel 37:24","text":"My servant David will be king over them, and there will be one shepherd for all of them. They will follow My ordinances and keep and observe My statutes."},{"ref":"Ezekiel 37:25","text":"They will live in the land that I gave to My servant Jacob, where your fathers lived. They will live there forever with their children and grandchildren, and My servant David will be their prince forever."},{"ref":"Ezekiel 37:26","text":"And I will make a covenant of peace with them; it will be an everlasting covenant. I will establish them and multiply them, and I will set My sanctuary among them forever."},{"ref":"Ezekiel 37:27","text":"My dwelling place will be with them; I will be their God, and they will be My people."},{"ref":"Ezekiel 37:28","text":"Then the nations will know that I the LORD sanctify Israel, when My sanctuary is among them forever.’”"}],"KJV":[{"ref":"Ezekiel 37:21","text":"And say unto them, Thus saith the Lord GOD; Behold, I will take the children of Israel from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land:"},{"ref":"Ezekiel 37:22","text":"And I will make them one nation in the land upon the mountains of Israel; and one king shall be king to them all: and they shall be no more two nations, neither shall they be divided into two kingdoms any more at all:"},{"ref":"Ezekiel 37:23","text":"Neither shall they defile themselves any more with their idols, nor with their detestable things, nor with any of their transgressions: but I will save them out of all their dwellingplaces, wherein they have sinned, and will cleanse them: so shall they be my people, and I will be their God."},{"ref":"Ezekiel 37:24","text":"And David my servant shall be king over them; and they all shall have one shepherd: they shall also walk in my judgments, and observe my statutes, and do them."},{"ref":"Ezekiel 37:25","text":"And they shall dwell in the land that I have given unto Jacob my servant, wherein your fathers have dwelt; and they shall dwell therein, even they, and their children, and their children's children for ever: and my servant David shall be their prince for ever."},{"ref":"Ezekiel 37:26","text":"Moreover I will make a covenant of peace with them; it shall be an everlasting covenant with them: and I will place them, and multiply them, and will set my sanctuary in the midst of them for evermore."},{"ref":"Ezekiel 37:27","text":"My tabernacle also shall be with them: yea, I will be their God, and they shall be my people."},{"ref":"Ezekiel 37:28","text":"And the heathen shall know that I the LORD do sanctify Israel, when my sanctuary shall be in the midst of them for evermore."}],"WEB":[{"ref":"Ezekiel 37:21","text":"Say to them, ‘The Lord Yahweh says: “Behold, I will take the children of Israel from among the nations, where they have gone, and will gather them on every side, and bring them into their own land."},{"ref":"Ezekiel 37:22","text":"I will make them one nation in the land, on the mountains of Israel. One king will be king to them all. They will no longer be two nations. They won’t be divided into two kingdoms any more at all."},{"ref":"Ezekiel 37:23","text":"They won’t defile themselves any more with their idols, nor with their detestable things, nor with any of their transgressions; but I will save them out of all their dwelling places, in which they have sinned, and will cleanse them. So they will be my people, and I will be their God."},{"ref":"Ezekiel 37:24","text":"“ ‘ “My servant David will be king over them. They all will have one shepherd. They will also walk in my ordinances, and observe my statutes, and do them."},{"ref":"Ezekiel 37:25","text":"They will dwell in the land that I have given to Jacob my servant, in which your fathers lived. They will dwell therein, they, and their children, and their children’s children, forever. David my servant will be their prince forever."},{"ref":"Ezekiel 37:26","text":"Moreover I will make a covenant of peace with them. It will be an everlasting covenant with them. I will place them, multiply them, and will set my sanctuary among them forever more."},{"ref":"Ezekiel 37:27","text":"My tent also will be with them. I will be their God, and they will be my people."},{"ref":"Ezekiel 37:28","text":"The nations will know that I am Yahweh who sanctifies Israel, when my sanctuary is among them forever more.” ’ ”"}]},"ezekiel-40-48-temple-vision":{"BSB":[{"ref":"Ezekiel 40:1","text":"In the twenty-fifth year of our exile, at the beginning of the year, on the tenth day of the month—in the fourteenth year after Jerusalem had been struck down—on that very day the hand of the LORD was upon me, and He took me there."},{"ref":"Ezekiel 40:2","text":"In visions of God He took me to the land of Israel and set me on a very high mountain, on whose southern slope was a structure that resembled a city."},{"ref":"Ezekiel 40:3","text":"So He took me there, and I saw a man whose appearance was like bronze. He was standing in the gateway with a linen cord and a measuring rod in his hand."},{"ref":"Ezekiel 40:4","text":"“Son of man,” he said to me, “look with your eyes, hear with your ears, and pay attention to everything I am going to show you, for that is why you have been brought here. Report to the house of Israel everything you see.”"},{"ref":"Ezekiel 47:1","text":"Then the man brought me back to the entrance of the temple, and I saw water flowing from under the threshold of the temple toward the east (for the temple faced east). The water was coming down from under the south side of the temple, south of the altar."},{"ref":"Ezekiel 47:2","text":"Next he brought me out through the north gate and led me around the outside to the outer gate facing east, and there I saw the water trickling out from the south side."},{"ref":"Ezekiel 47:3","text":"As the man went eastward with a measuring line in his hand, he measured off a thousand cubits and led me through ankle-deep water."},{"ref":"Ezekiel 47:4","text":"Then he measured off a thousand cubits and led me through knee-deep water. Again he measured a thousand cubits and led me through waist-deep water."},{"ref":"Ezekiel 47:5","text":"Once again he measured off a thousand cubits, but now it was a river that I could not cross, because the water had risen and was deep enough for swimming—a river that could not be crossed on foot."},{"ref":"Ezekiel 47:6","text":"“Son of man, do you see this?” he asked. Then he led me back to the bank of the river."},{"ref":"Ezekiel 47:7","text":"When I arrived, I saw a great number of trees along both banks of the river."},{"ref":"Ezekiel 47:8","text":"And he said to me, “This water flows out to the eastern region and goes down into the Arabah. When it empties into the Sea, the water there becomes fresh."},{"ref":"Ezekiel 47:9","text":"Wherever the river flows, there will be swarms of living creatures and a great number of fish, because it flows there and makes the waters fresh; so wherever the river flows, everything will flourish."},{"ref":"Ezekiel 47:10","text":"Fishermen will stand by the shore; from En-gedi to En-eglaim they will spread their nets to catch fish of many kinds, like the fish of the Great Sea."},{"ref":"Ezekiel 47:11","text":"But the swamps and marshes will not become fresh; they will be left for salt."},{"ref":"Ezekiel 47:12","text":"Along both banks of the river, fruit trees of all kinds will grow. Their leaves will not wither, and their fruit will not fail. Each month they will bear fruit, because the water from the sanctuary flows to them. Their fruit will be used for food and their leaves for healing.”"}],"KJV":[{"ref":"Ezekiel 40:1","text":"In the five and twentieth year of our captivity, in the beginning of the year, in the tenth day of the month, in the fourteenth year after that the city was smitten, in the selfsame day the hand of the LORD was upon me, and brought me thither."},{"ref":"Ezekiel 40:2","text":"In the visions of God brought he me into the land of Israel, and set me upon a very high mountain, by which was as the frame of a city on the south."},{"ref":"Ezekiel 40:3","text":"And he brought me thither, and, behold, there was a man, whose appearance was like the appearance of brass, with a line of flax in his hand, and a measuring reed; and he stood in the gate."},{"ref":"Ezekiel 40:4","text":"And the man said unto me, Son of man, behold with thine eyes, and hear with thine ears, and set thine heart upon all that I shall shew thee; for to the intent that I might shew them unto thee art thou brought hither: declare all that thou seest to the house of Israel."},{"ref":"Ezekiel 47:1","text":"Afterward he brought me again unto the door of the house; and, behold, waters issued out from under the threshold of the house eastward: for the forefront of the house stood toward the east, and the waters came down from under from the right side of the house, at the south side of the altar."},{"ref":"Ezekiel 47:2","text":"Then brought he me out of the way of the gate northward, and led me about the way without unto the utter gate by the way that looketh eastward; and, behold, there ran out waters on the right side."},{"ref":"Ezekiel 47:3","text":"And when the man that had the line in his hand went forth eastward, he measured a thousand cubits, and he brought me through the waters; the waters were to the ancles."},{"ref":"Ezekiel 47:4","text":"Again he measured a thousand, and brought me through the waters; the waters were to the knees. Again he measured a thousand, and brought me through; the waters were to the loins."},{"ref":"Ezekiel 47:5","text":"Afterward he measured a thousand; and it was a river that I could not pass over: for the waters were risen, waters to swim in, a river that could not be passed over."},{"ref":"Ezekiel 47:6","text":"# And he said unto me, Son of man, hast thou seen this? Then he brought me, and caused me to return to the brink of the river."},{"ref":"Ezekiel 47:7","text":"Now when I had returned, behold, at the bank of the river were very many trees on the one side and on the other."},{"ref":"Ezekiel 47:8","text":"Then said he unto me, These waters issue out toward the east country, and go down into the desert, and go into the sea: which being brought forth into the sea, the waters shall be healed."},{"ref":"Ezekiel 47:9","text":"And it shall come to pass, that every thing that liveth, which moveth, whithersoever the rivers shall come, shall live: and there shall be a very great multitude of fish, because these waters shall come thither: for they shall be healed; and every thing shall live whither the river cometh."},{"ref":"Ezekiel 47:10","text":"And it shall come to pass, that the fishers shall stand upon it from En-gedi even unto En-eglaim; they shall be a place to spread forth nets; their fish shall be according to their kinds, as the fish of the great sea, exceeding many."},{"ref":"Ezekiel 47:11","text":"But the miry places thereof and the marishes thereof shall not be healed; they shall be given to salt."},{"ref":"Ezekiel 47:12","text":"And by the river upon the bank thereof, on this side and on that side, shall grow all trees for meat, whose leaf shall not fade, neither shall the fruit thereof be consumed: it shall bring forth new fruit according to his months, because their waters they issued out of the sanctuary: and the fruit thereof shall be for meat, and the leaf thereof for medicine."}],"WEB":[{"ref":"Ezekiel 40:1","text":"In the twenty-fifth year of our captivity, in the beginning of the year, in the tenth day of the month, in the fourteenth year after that the city was struck, in the same day, Yahweh’s hand was on me, and he brought me there."},{"ref":"Ezekiel 40:2","text":"In the visions of God he brought me into the land of Israel, and set me down on a very high mountain, on which was something like the frame of a city to the south."},{"ref":"Ezekiel 40:3","text":"He brought me there; and, behold, there was a man, whose appearance was like the appearance of bronze, with a line of flax in his hand, and a measuring reed; and he stood in the gate."},{"ref":"Ezekiel 40:4","text":"The man said to me, “Son of man, see with your eyes, and hear with your ears, and set your heart on all that I will show you; for you have been brought here so that I may show them to you. Declare all that you see to the house of Israel.”"},{"ref":"Ezekiel 47:1","text":"He brought me back to the door of the house; and behold, waters flowed out from under the threshold of the house eastward, for the front of the house faced toward the east. The waters came down from underneath, from the right side of the house, on the south of the altar."},{"ref":"Ezekiel 47:2","text":"Then he brought me out by the way of the gate northward, and led me around by the way outside to the outer gate, by the way of the gate that looks toward the east. Behold, waters ran out on the right side."},{"ref":"Ezekiel 47:3","text":"When the man went out eastward with the line in his hand, he measured one thousand cubits, and he caused me to pass through the waters, waters that were to the ankles."},{"ref":"Ezekiel 47:4","text":"Again he measured one thousand, and caused me to pass through the waters, waters that were to the knees. Again he measured one thousand, and caused me to pass through waters that were to the waist."},{"ref":"Ezekiel 47:5","text":"Afterward he measured one thousand; and it was a river that I could not pass through; for the waters had risen, waters to swim in, a river that could not be walked through."},{"ref":"Ezekiel 47:6","text":"He said to me, “Son of man, have you seen?” Then he brought me, and caused me to return to the bank of the river."},{"ref":"Ezekiel 47:7","text":"Now when I had returned, behold, on the bank of the river were very many trees on the one side and on the other."},{"ref":"Ezekiel 47:8","text":"Then he said to me, “These waters flow out toward the eastern region, and will go down into the Arabah. Then they will go toward the sea; and flow into the sea which will be made to flow out; and the waters will be healed."},{"ref":"Ezekiel 47:9","text":"It will happen, that every living creature which swarms, in every place where the rivers come, will live. Then there will be a very great multitude of fish; for these waters have come there, and the waters of the sea will be healed, and everything will live wherever the river comes."},{"ref":"Ezekiel 47:10","text":"It will happen, that fishermen will stand by it. From En Gedi even to En Eglaim will be a place for the spreading of nets. Their fish will be after their kinds, as the fish of the great sea, exceedingly many."},{"ref":"Ezekiel 47:11","text":"But the miry places of it, and its marshes, will not be healed. They will be given up to salt."},{"ref":"Ezekiel 47:12","text":"By the river on its bank, on this side and on that side, will grow every tree for food, whose leaf won’t wither, neither will its fruit fail. It will produce new fruit every month, because its waters issue out of the sanctuary. Its fruit will be for food, and its leaf for healing.”"}]},"zechariah-12-10-pierced-one":{"BSB":[{"ref":"Zechariah 12:10","text":"Then I will pour out on the house of David and on the people of Jerusalem a spirit of grace and prayer, and they will look on Me, the One they have pierced. They will mourn for Him as one mourns for an only child, and grieve bitterly for Him as one grieves for a firstborn son."}],"KJV":[{"ref":"Zechariah 12:10","text":"And I will pour upon the house of David, and upon the inhabitants of Jerusalem, the spirit of grace and of supplications: and they shall look upon me whom they have pierced, and they shall mourn for him, as one mourneth for his only son, and shall be in bitterness for him, as one that is in bitterness for his firstborn."}],"WEB":[{"ref":"Zechariah 12:10","text":"I will pour on David’s house, and on the inhabitants of Jerusalem, the spirit of grace and of supplication; and they will look to me whom they have pierced; and they shall mourn for him, as one mourns for his only son, and will grieve bitterly for him, as one grieves for his firstborn."}]},"zechariah-14-day-of-the-lord":{"BSB":[{"ref":"Zechariah 14:1","text":"Behold, a day of the LORD is coming when your plunder will be divided in your presence."},{"ref":"Zechariah 14:2","text":"For I will gather all the nations for battle against Jerusalem, and the city will be captured, the houses looted, and the women ravished. Half of the city will go into exile, but the rest of the people will not be removed from the city."},{"ref":"Zechariah 14:3","text":"Then the LORD will go out to fight against those nations, as He fights in the day of battle."},{"ref":"Zechariah 14:4","text":"On that day His feet will stand on the Mount of Olives, east of Jerusalem, and the Mount of Olives will be split in two from east to west, forming a great valley, with half the mountain moving to the north and half to the south."},{"ref":"Zechariah 14:5","text":"You will flee by My mountain valley, for it will extend to Azal. You will flee as you fled from the earthquake in the days of Uzziah king of Judah. Then the LORD my God will come, and all the holy ones with Him."},{"ref":"Zechariah 14:6","text":"On that day there will be no light, no cold or frost."},{"ref":"Zechariah 14:7","text":"It will be a day known only to the LORD, without day or night; but when evening comes, there will be light."},{"ref":"Zechariah 14:8","text":"And on that day living water will flow out from Jerusalem, half of it toward the Eastern Sea and the other half toward the Western Sea, in summer and winter alike."},{"ref":"Zechariah 14:9","text":"On that day the LORD will become King over all the earth—the LORD alone, and His name alone."},{"ref":"Zechariah 14:10","text":"All the land from Geba to Rimmon south of Jerusalem will be turned into a plain, but Jerusalem will be raised up and will remain in her place, from the Benjamin Gate to the site of the First Gate to the Corner Gate, and from the Tower of Hananel to the royal winepresses."},{"ref":"Zechariah 14:11","text":"People will live there, and never again will there be an utter destruction. So Jerusalem will dwell securely."}],"KJV":[{"ref":"Zechariah 14:1","text":"Behold, the day of the LORD cometh, and thy spoil shall be divided in the midst of thee."},{"ref":"Zechariah 14:2","text":"For I will gather all nations against Jerusalem to battle; and the city shall be taken, and the houses rifled, and the women ravished; and half of the city shall go forth into captivity, and the residue of the people shall not be cut off from the city."},{"ref":"Zechariah 14:3","text":"Then shall the LORD go forth, and fight against those nations, as when he fought in the day of battle."},{"ref":"Zechariah 14:4","text":"# And his feet shall stand in that day upon the mount of Olives, which is before Jerusalem on the east, and the mount of Olives shall cleave in the midst thereof toward the east and toward the west, and there shall be a very great valley; and half of the mountain shall remove toward the north, and half of it toward the south."},{"ref":"Zechariah 14:5","text":"And ye shall flee to the valley of the mountains; for the valley of the mountains shall reach unto Azal: yea, ye shall flee, like as ye fled from before the earthquake in the days of Uzziah king of Judah: and the LORD my God shall come, and all the saints with thee."},{"ref":"Zechariah 14:6","text":"And it shall come to pass in that day, that the light shall not be clear, nor dark:"},{"ref":"Zechariah 14:7","text":"But it shall be one day which shall be known to the LORD, not day, nor night: but it shall come to pass, that at evening time it shall be light."},{"ref":"Zechariah 14:8","text":"And it shall be in that day, that living waters shall go out from Jerusalem; half of them toward the former sea, and half of them toward the hinder sea: in summer and in winter shall it be."},{"ref":"Zechariah 14:9","text":"And the LORD shall be king over all the earth: in that day shall there be one LORD, and his name one."},{"ref":"Zechariah 14:10","text":"All the land shall be turned as a plain from Geba to Rimmon south of Jerusalem: and it shall be lifted up, and inhabited in her place, from Benjamin's gate unto the place of the first gate, unto the corner gate, and from the tower of Hananeel unto the king's winepresses."},{"ref":"Zechariah 14:11","text":"And men shall dwell in it, and there shall be no more utter destruction; but Jerusalem shall be safely inhabited."}],"WEB":[{"ref":"Zechariah 14:1","text":"Behold, a day of Yahweh comes, when your plunder will be divided within you."},{"ref":"Zechariah 14:2","text":"For I will gather all nations against Jerusalem to battle; and the city will be taken, the houses rifled, and the women ravished. Half of the city will go out into captivity, and the rest of the people will not be cut off from the city."},{"ref":"Zechariah 14:3","text":"Then Yahweh will go out and fight against those nations, as when he fought in the day of battle."},{"ref":"Zechariah 14:4","text":"His feet will stand in that day on the Mount of Olives, which is before Jerusalem on the east; and the Mount of Olives will be split in two, from east to west, making a very great valley. Half of the mountain will move toward the north, and half of it toward the south."},{"ref":"Zechariah 14:5","text":"You shall flee by the valley of my mountains; for the valley of the mountains shall reach to Azel; yes, you shall flee, just like you fled from before the earthquake in the days of Uzziah king of Judah. Yahweh my God will come, and all the holy ones with you."},{"ref":"Zechariah 14:6","text":"It will happen in that day, that there will not be light, cold, or frost."},{"ref":"Zechariah 14:7","text":"It will be a unique day which is known to Yahweh; not day, and not night; but it will come to pass, that at evening time there will be light."},{"ref":"Zechariah 14:8","text":"It will happen in that day, that living waters will go out from Jerusalem: half of them toward the eastern sea, and half of them toward the western sea. It will be so in summer and in winter."},{"ref":"Zechariah 14:9","text":"Yahweh will be King over all the earth. In that day Yahweh will be one, and his name one."},{"ref":"Zechariah 14:10","text":"All the land will be made like the Arabah, from Geba to Rimmon south of Jerusalem; and she will be lifted up, and will dwell in her place, from Benjamin’s gate to the place of the first gate, to the corner gate, and from the tower of Hananel to the king’s wine presses."},{"ref":"Zechariah 14:11","text":"Men will dwell therein, and there will be no more curse; but Jerusalem will dwell safely."}]},"matthew-13-kingdom-parables":{"BSB":[{"ref":"Matthew 13:24","text":"Jesus put before them another parable: “The kingdom of heaven is like a man who sowed good seed in his field."},{"ref":"Matthew 13:25","text":"But while everyone was asleep, his enemy came and sowed weeds among the wheat, and slipped away."},{"ref":"Matthew 13:26","text":"When the wheat sprouted and bore grain, then the weeds also appeared."},{"ref":"Matthew 13:27","text":"The owner’s servants came to him and said, ‘Sir, didn’t you sow good seed in your field? Where then did the weeds come from?’"},{"ref":"Matthew 13:28","text":"‘An enemy did this,’ he replied. So the servants asked him, ‘Do you want us to go and pull them up?’"},{"ref":"Matthew 13:29","text":"‘No,’ he said, ‘if you pull the weeds now, you might uproot the wheat with them."},{"ref":"Matthew 13:30","text":"Let both grow together until the harvest. At that time I will tell the harvesters: First collect the weeds and tie them in bundles to be burned; then gather the wheat into my barn.’”"},{"ref":"Matthew 13:31","text":"He put before them another parable: “The kingdom of heaven is like a mustard seed that a man planted in his field."},{"ref":"Matthew 13:32","text":"Although it is the smallest of all seeds, yet it grows into the largest of garden plants and becomes a tree, so that the birds of the air come and nest in its branches.”"},{"ref":"Matthew 13:33","text":"He told them still another parable: “The kingdom of heaven is like leaven that a woman took and mixed into three measures of flour, until all of it was leavened.”"},{"ref":"Matthew 13:34","text":"Jesus spoke all these things to the crowds in parables. He did not tell them anything without using a parable."},{"ref":"Matthew 13:35","text":"So was fulfilled what was spoken through the prophet: “I will open My mouth in parables; I will utter things hidden since the foundation of the world.”"},{"ref":"Matthew 13:36","text":"Then Jesus dismissed the crowds and went into the house. His disciples came to Him and said, “Explain to us the parable of the weeds in the field.”"},{"ref":"Matthew 13:37","text":"He replied, “The One who sows the good seed is the Son of Man."},{"ref":"Matthew 13:38","text":"The field is the world, and the good seed represents the sons of the kingdom. The weeds are the sons of the evil one,"},{"ref":"Matthew 13:39","text":"and the enemy who sows them is the devil. The harvest is the end of the age, and the harvesters are angels."},{"ref":"Matthew 13:40","text":"As the weeds are collected and burned in the fire, so will it be at the end of the age."},{"ref":"Matthew 13:41","text":"The Son of Man will send out His angels, and they will weed out of His kingdom every cause of sin and all who practice lawlessness."},{"ref":"Matthew 13:42","text":"And they will throw them into the fiery furnace, where there will be weeping and gnashing of teeth."},{"ref":"Matthew 13:43","text":"Then the righteous will shine like the sun in the kingdom of their Father. He who has ears, let him hear."}],"KJV":[{"ref":"Matthew 13:24","text":"# Another parable put he forth unto them, saying, The kingdom of heaven is likened unto a man which sowed good seed in his field:"},{"ref":"Matthew 13:25","text":"But while men slept, his enemy came and sowed tares among the wheat, and went his way."},{"ref":"Matthew 13:26","text":"But when the blade was sprung up, and brought forth fruit, then appeared the tares also."},{"ref":"Matthew 13:27","text":"So the servants of the householder came and said unto him, Sir, didst not thou sow good seed in thy field? from whence then hath it tares?"},{"ref":"Matthew 13:28","text":"He said unto them, An enemy hath done this. The servants said unto him, Wilt thou then that we go and gather them up?"},{"ref":"Matthew 13:29","text":"But he said, Nay; lest while ye gather up the tares, ye root up also the wheat with them."},{"ref":"Matthew 13:30","text":"Let both grow together until the harvest: and in the time of harvest I will say to the reapers, Gather ye together first the tares, and bind them in bundles to burn them: but gather the wheat into my barn."},{"ref":"Matthew 13:31","text":"# Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field:"},{"ref":"Matthew 13:32","text":"Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof."},{"ref":"Matthew 13:33","text":"# Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened."},{"ref":"Matthew 13:34","text":"All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them:"},{"ref":"Matthew 13:35","text":"That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world."},{"ref":"Matthew 13:36","text":"Then Jesus sent the multitude away, and went into the house: and his disciples came unto him, saying, Declare unto us the parable of the tares of the field."},{"ref":"Matthew 13:37","text":"He answered and said unto them, He that soweth the good seed is the Son of man;"},{"ref":"Matthew 13:38","text":"The field is the world; the good seed are the children of the kingdom; but the tares are the children of the wicked one;"},{"ref":"Matthew 13:39","text":"The enemy that sowed them is the devil; the harvest is the end of the world; and the reapers are the angels."},{"ref":"Matthew 13:40","text":"As therefore the tares are gathered and burned in the fire; so shall it be in the end of this world."},{"ref":"Matthew 13:41","text":"The Son of man shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity;"},{"ref":"Matthew 13:42","text":"And shall cast them into a furnace of fire: there shall be wailing and gnashing of teeth."},{"ref":"Matthew 13:43","text":"Then shall the righteous shine forth as the sun in the kingdom of their Father. Who hath ears to hear, let him hear."}],"WEB":[{"ref":"Matthew 13:24","text":"He set another parable before them, saying, “The Kingdom of Heaven is like a man who sowed good seed in his field,"},{"ref":"Matthew 13:25","text":"but while people slept, his enemy came and sowed darnel weeds also among the wheat, and went away."},{"ref":"Matthew 13:26","text":"But when the blade sprang up and produced fruit, then the darnel weeds appeared also."},{"ref":"Matthew 13:27","text":"The servants of the householder came and said to him, ‘Sir, didn’t you sow good seed in your field? Where did these darnel weeds come from?’"},{"ref":"Matthew 13:28","text":"“He said to them, ‘An enemy has done this.’ “The servants asked him, ‘Do you want us to go and gather them up?’"},{"ref":"Matthew 13:29","text":"“But he said, ‘No, lest perhaps while you gather up the darnel weeds, you root up the wheat with them."},{"ref":"Matthew 13:30","text":"Let both grow together until the harvest, and in the harvest time I will tell the reapers, “First, gather up the darnel weeds, and bind them in bundles to burn them; but gather the wheat into my barn.” ’ ”"},{"ref":"Matthew 13:31","text":"He set another parable before them, saying, “The Kingdom of Heaven is like a grain of mustard seed, which a man took, and sowed in his field;"},{"ref":"Matthew 13:32","text":"which indeed is smaller than all seeds. But when it is grown, it is greater than the herbs, and becomes a tree, so that the birds of the air come and lodge in its branches.”"},{"ref":"Matthew 13:33","text":"He spoke another parable to them. “The Kingdom of Heaven is like yeast, which a woman took, and hid in three measures of meal, until it was all leavened.”"},{"ref":"Matthew 13:34","text":"Jesus spoke all these things in parables to the multitudes; and without a parable, he didn’t speak to them,"},{"ref":"Matthew 13:35","text":"that it might be fulfilled which was spoken through the prophet, saying, “I will open my mouth in parables; I will utter things hidden from the foundation of the world.”"},{"ref":"Matthew 13:36","text":"Then Jesus sent the multitudes away, and went into the house. His disciples came to him, saying, “Explain to us the parable of the darnel weeds of the field.”"},{"ref":"Matthew 13:37","text":"He answered them, “He who sows the good seed is the Son of Man,"},{"ref":"Matthew 13:38","text":"the field is the world; and the good seed, these are the children of the Kingdom; and the darnel weeds are the children of the evil one."},{"ref":"Matthew 13:39","text":"The enemy who sowed them is the devil. The harvest is the end of the age, and the reapers are angels."},{"ref":"Matthew 13:40","text":"As therefore the darnel weeds are gathered up and burned with fire; so will it be at the end of this age."},{"ref":"Matthew 13:41","text":"The Son of Man will send out his angels, and they will gather out of his Kingdom all things that cause stumbling, and those who do iniquity,"},{"ref":"Matthew 13:42","text":"and will cast them into the furnace of fire. There will be the weeping and the gnashing of teeth."},{"ref":"Matthew 13:43","text":"Then the righteous will shine like the sun in the Kingdom of their Father. He who has ears to hear, let him hear."}]},"matthew-28-great-commission":{"BSB":[{"ref":"Matthew 28:18","text":"Then Jesus came to them and said, “All authority in heaven and on earth has been given to Me."},{"ref":"Matthew 28:19","text":"Therefore go and make disciples of all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Spirit,"},{"ref":"Matthew 28:20","text":"and teaching them to obey all that I have commanded you. And surely I am with you always, even to the end of the age.”"}],"KJV":[{"ref":"Matthew 28:18","text":"And Jesus came and spake unto them, saying, All power is given unto me in heaven and in earth."},{"ref":"Matthew 28:19","text":"# Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:"},{"ref":"Matthew 28:20","text":"Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen."}],"WEB":[{"ref":"Matthew 28:18","text":"Jesus came to them and spoke to them, saying, “All authority has been given to me in heaven and on earth."},{"ref":"Matthew 28:19","text":"Go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,"},{"ref":"Matthew 28:20","text":"teaching them to observe all things that I commanded you. Behold, I am with you always, even to the end of the age.” Amen."}]},"matthew-10-23-cities-of-israel":{"BSB":[{"ref":"Matthew 10:23","text":"When they persecute you in one town, flee to the next. Truly I tell you, you will not reach all the towns of Israel before the Son of Man comes."}],"KJV":[{"ref":"Matthew 10:23","text":"But when they persecute you in this city, flee ye into another: for verily I say unto you, Ye shall not have gone over the cities of Israel, till the Son of man be come."}],"WEB":[{"ref":"Matthew 10:23","text":"But when they persecute you in this city, flee into the next, for most certainly I tell you, you will not have gone through the cities of Israel until the Son of Man has come."}]},"matthew-16-27-28-some-standing-here":{"BSB":[{"ref":"Matthew 16:27","text":"For the Son of Man will come in His Father’s glory with His angels, and then He will repay each one according to what he has done."},{"ref":"Matthew 16:28","text":"Truly I tell you, some who are standing here will not taste death before they see the Son of Man coming in His kingdom.”"}],"KJV":[{"ref":"Matthew 16:27","text":"For the Son of man shall come in the glory of his Father with his angels; and then he shall reward every man according to his works."},{"ref":"Matthew 16:28","text":"Verily I say unto you, There be some standing here, which shall not taste of death, till they see the Son of man coming in his kingdom."}],"WEB":[{"ref":"Matthew 16:27","text":"For the Son of Man will come in the glory of his Father with his angels, and then he will render to everyone according to his deeds."},{"ref":"Matthew 16:28","text":"Most certainly I tell you, there are some standing here who will in no way taste of death, until they see the Son of Man coming in his Kingdom.”"}]},"john-5-28-29-hour-of-resurrection":{"BSB":[{"ref":"John 5:28","text":"Do not be amazed at this, for the hour is coming when all who are in their graves will hear His voice"},{"ref":"John 5:29","text":"and come out—those who have done good to the resurrection of life, and those who have done evil to the resurrection of judgment."}],"KJV":[{"ref":"John 5:28","text":"Marvel not at this: for the hour is coming, in the which all that are in the graves shall hear his voice,"},{"ref":"John 5:29","text":"And shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation."}],"WEB":[{"ref":"John 5:28","text":"Don’t marvel at this, for the hour comes in which all who are in the tombs will hear his voice,"},{"ref":"John 5:29","text":"and will come out; those who have done good, to the resurrection of life; and those who have done evil, to the resurrection of judgment."}]},"acts-1-6-11-restore-the-kingdom":{"BSB":[{"ref":"Acts 1:6","text":"So when they came together, they asked Him, “Lord, will You at this time restore the kingdom to Israel?”"},{"ref":"Acts 1:7","text":"Jesus replied, “It is not for you to know times or seasons that the Father has fixed by His own authority."},{"ref":"Acts 1:8","text":"But you will receive power when the Holy Spirit comes upon you, and you will be My witnesses in Jerusalem, and in all Judea and Samaria, and to the ends of the earth.”"},{"ref":"Acts 1:9","text":"After He had said this, they watched as He was taken up, and a cloud hid Him from their sight."},{"ref":"Acts 1:10","text":"They were looking intently into the sky as He was going, when suddenly two men dressed in white stood beside them."},{"ref":"Acts 1:11","text":"“Men of Galilee,” they said, “why do you stand here looking into the sky? This same Jesus, who has been taken from you into heaven, will come back in the same way you have seen Him go into heaven.”"}],"KJV":[{"ref":"Acts 1:6","text":"When they therefore were come together, they asked of him, saying, Lord, wilt thou at this time restore again the kingdom to Israel?"},{"ref":"Acts 1:7","text":"And he said unto them, It is not for you to know the times or the seasons, which the Father hath put in his own power."},{"ref":"Acts 1:8","text":"But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth."},{"ref":"Acts 1:9","text":"And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight."},{"ref":"Acts 1:10","text":"And while they looked stedfastly toward heaven as he went up, behold, two men stood by them in white apparel;"},{"ref":"Acts 1:11","text":"Which also said, Ye men of Galilee, why stand ye gazing up into heaven? this same Jesus, which is taken up from you into heaven, shall so come in like manner as ye have seen him go into heaven."}],"WEB":[{"ref":"Acts 1:6","text":"Therefore when they had come together, they asked him, “Lord, are you now restoring the kingdom to Israel?”"},{"ref":"Acts 1:7","text":"He said to them, “It isn’t for you to know times or seasons which the Father has set within his own authority."},{"ref":"Acts 1:8","text":"But you will receive power when the Holy Spirit has come upon you. You will be witnesses to me in Jerusalem, in all Judea and Samaria, and to the uttermost parts of the earth.”"},{"ref":"Acts 1:9","text":"When he had said these things, as they were looking, he was taken up, and a cloud received him out of their sight."},{"ref":"Acts 1:10","text":"While they were looking steadfastly into the sky as he went, behold, two men stood by them in white clothing,"},{"ref":"Acts 1:11","text":"who also said, “You men of Galilee, why do you stand looking into the sky? This Jesus, who was received up from you into the sky, will come back in the same way as you saw him going into the sky.”"}]},"acts-3-19-21-restoration-of-all-things":{"BSB":[{"ref":"Acts 3:19","text":"Repent, then, and turn back, so that your sins may be wiped away,"},{"ref":"Acts 3:20","text":"that times of refreshing may come from the presence of the Lord, and that He may send Jesus, the Christ, who has been appointed for you."},{"ref":"Acts 3:21","text":"Heaven must take Him in until the time comes for the restoration of all things, which God announced long ago through His holy prophets."}],"KJV":[{"ref":"Acts 3:19","text":"# Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord;"},{"ref":"Acts 3:20","text":"And he shall send Jesus Christ, which before was preached unto you:"},{"ref":"Acts 3:21","text":"Whom the heaven must receive until the times of restitution of all things, which God hath spoken by the mouth of all his holy prophets since the world began."}],"WEB":[{"ref":"Acts 3:19","text":"“Repent therefore, and turn again, that your sins may be blotted out, so that there may come times of refreshing from the presence of the Lord,"},{"ref":"Acts 3:20","text":"and that he may send Christ Jesus, who was ordained for you before,"},{"ref":"Acts 3:21","text":"whom heaven must receive until the times of restoration of all things, which God spoke long ago by the mouth of his holy prophets."}]},"2-peter-3-day-of-the-lord":{"BSB":[{"ref":"2 Peter 3:1","text":"Beloved, this is now my second letter to you. Both of them are reminders to stir you to wholesome thinking"},{"ref":"2 Peter 3:2","text":"by recalling what was foretold by the holy prophets and commanded by our Lord and Savior through your apostles."},{"ref":"2 Peter 3:3","text":"Most importantly, you must understand that in the last days scoffers will come, scoffing and following their own evil desires."},{"ref":"2 Peter 3:4","text":"“Where is the promise of His coming?” they will ask. “Ever since our fathers fell asleep, everything continues as it has from the beginning of creation.”"},{"ref":"2 Peter 3:5","text":"But they deliberately overlook the fact that long ago by God’s word the heavens existed and the earth was formed out of water and by water,"},{"ref":"2 Peter 3:6","text":"through which the world of that time perished in the flood."},{"ref":"2 Peter 3:7","text":"And by that same word, the present heavens and earth are reserved for fire, being kept for the day of judgment and destruction of ungodly men."},{"ref":"2 Peter 3:8","text":"Beloved, do not let this one thing escape your notice: With the Lord a day is like a thousand years, and a thousand years are like a day."},{"ref":"2 Peter 3:9","text":"The Lord is not slow in keeping His promise as some understand slowness, but is patient with you, not wanting anyone to perish but everyone to come to repentance."},{"ref":"2 Peter 3:10","text":"But the Day of the Lord will come like a thief. The heavens will disappear with a roar, the elements will be destroyed by fire, and the earth and its works will be laid bare."},{"ref":"2 Peter 3:11","text":"Since everything will be destroyed in this way, what kind of people ought you to be? You ought to conduct yourselves in holiness and godliness"},{"ref":"2 Peter 3:12","text":"as you anticipate and hasten the coming of the day of God, when the heavens will be destroyed by fire and the elements will melt in the heat."},{"ref":"2 Peter 3:13","text":"But in keeping with God’s promise, we are looking forward to a new heaven and a new earth, where righteousness dwells."}],"KJV":[{"ref":"2 Peter 3:1","text":"This second epistle, beloved, I now write unto you; in both which I stir up your pure minds by way of remembrance:"},{"ref":"2 Peter 3:2","text":"That ye may be mindful of the words which were spoken before by the holy prophets, and of the commandment of us the apostles of the Lord and Saviour:"},{"ref":"2 Peter 3:3","text":"Knowing this first, that there shall come in the last days scoffers, walking after their own lusts,"},{"ref":"2 Peter 3:4","text":"And saying, Where is the promise of his coming? for since the fathers fell asleep, all things continue as they were from the beginning of the creation."},{"ref":"2 Peter 3:5","text":"For this they willingly are ignorant of, that by the word of God the heavens were of old, and the earth standing out of the water and in the water:"},{"ref":"2 Peter 3:6","text":"Whereby the world that then was, being overflowed with water, perished:"},{"ref":"2 Peter 3:7","text":"But the heavens and the earth, which are now, by the same word are kept in store, reserved unto fire against the day of judgment and perdition of ungodly men."},{"ref":"2 Peter 3:8","text":"But, beloved, be not ignorant of this one thing, that one day is with the Lord as a thousand years, and a thousand years as one day."},{"ref":"2 Peter 3:9","text":"The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance."},{"ref":"2 Peter 3:10","text":"But the day of the Lord will come as a thief in the night; in the which the heavens shall pass away with a great noise, and the elements shall melt with fervent heat, the earth also and the works that are therein shall be burned up."},{"ref":"2 Peter 3:11","text":"Seeing then that all these things shall be dissolved, what manner of persons ought ye to be in all holy conversation and godliness,"},{"ref":"2 Peter 3:12","text":"Looking for and hasting unto the coming of the day of God, wherein the heavens being on fire shall be dissolved, and the elements shall melt with fervent heat?"},{"ref":"2 Peter 3:13","text":"Nevertheless we, according to his promise, look for new heavens and a new earth, wherein dwelleth righteousness."}],"WEB":[{"ref":"2 Peter 3:1","text":"This is now, beloved, the second letter that I have written to you; and in both of them I stir up your sincere mind by reminding you,"},{"ref":"2 Peter 3:2","text":"that you should remember the words which were spoken before by the holy prophets, and the commandment of us, the apostles of the Lord and Savior:"},{"ref":"2 Peter 3:3","text":"knowing this first, that in the last days mockers will come, walking after their own lusts"},{"ref":"2 Peter 3:4","text":"and saying, “Where is the promise of his coming? For, from the day that the fathers fell asleep, all things continue as they were from the beginning of the creation.”"},{"ref":"2 Peter 3:5","text":"For this they willfully forget that there were heavens from of old, and an earth formed out of water and amid water by the word of God,"},{"ref":"2 Peter 3:6","text":"by which means the world that existed then, being overflowed with water, perished."},{"ref":"2 Peter 3:7","text":"But the heavens that exist now and the earth, by the same word have been stored up for fire, being reserved against the day of judgment and destruction of ungodly men."},{"ref":"2 Peter 3:8","text":"But don’t forget this one thing, beloved, that one day is with the Lord as a thousand years, and a thousand years as one day."},{"ref":"2 Peter 3:9","text":"The Lord is not slow concerning his promise, as some count slowness; but he is patient with us, not wishing that anyone should perish, but that all should come to repentance."},{"ref":"2 Peter 3:10","text":"But the day of the Lord will come as a thief in the night; in which the heavens will pass away with a great noise, and the elements will be dissolved with fervent heat, and the earth and the works that are in it will be burned up."},{"ref":"2 Peter 3:11","text":"Therefore since all these things will be destroyed like this, what kind of people ought you to be in holy living and godliness,"},{"ref":"2 Peter 3:12","text":"looking for and earnestly desiring the coming of the day of God, which will cause the burning heavens to be dissolved, and the elements will melt with fervent heat?"},{"ref":"2 Peter 3:13","text":"But, according to his promise, we look for new heavens and a new earth, in which righteousness dwells."}]},"hebrews-8-13-ready-to-vanish":{"BSB":[{"ref":"Hebrews 8:13","text":"By speaking of a new covenant, He has made the first one obsolete; and what is obsolete and aging will soon disappear."}],"KJV":[{"ref":"Hebrews 8:13","text":"In that he saith, A new covenant, he hath made the first old. Now that which decayeth and waxeth old is ready to vanish away."}],"WEB":[{"ref":"Hebrews 8:13","text":"In that he says, “A new covenant”, he has made the first old. But that which is becoming old and grows aged is near to vanishing away."}]},"hebrews-12-22-28-unshakable-kingdom":{"BSB":[{"ref":"Hebrews 12:22","text":"Instead, you have come to Mount Zion, to the city of the living God, the heavenly Jerusalem. You have come to myriads of angels"},{"ref":"Hebrews 12:23","text":"in joyful assembly, to the congregation of the firstborn, enrolled in heaven. You have come to God the Judge of all, to the spirits of the righteous made perfect,"},{"ref":"Hebrews 12:24","text":"to Jesus the mediator of a new covenant, and to the sprinkled blood that speaks a better word than the blood of Abel."},{"ref":"Hebrews 12:25","text":"See to it that you do not refuse Him who speaks. For if the people did not escape when they refused Him who warned them on earth, how much less will we escape if we reject Him who warns us from heaven?"},{"ref":"Hebrews 12:26","text":"At that time His voice shook the earth, but now He has promised, “Once more I will shake not only the earth, but heaven as well.”"},{"ref":"Hebrews 12:27","text":"The words “Once more” signify the removal of what can be shaken—that is, created things—so that the unshakable may remain."},{"ref":"Hebrews 12:28","text":"Therefore, since we are receiving an unshakable kingdom, let us be filled with gratitude, and so worship God acceptably with reverence and awe."}],"KJV":[{"ref":"Hebrews 12:22","text":"But ye are come unto mount Sion, and unto the city of the living God, the heavenly Jerusalem, and to an innumerable company of angels,"},{"ref":"Hebrews 12:23","text":"To the general assembly and church of the firstborn, which are written in heaven, and to God the Judge of all, and to the spirits of just men made perfect,"},{"ref":"Hebrews 12:24","text":"And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel."},{"ref":"Hebrews 12:25","text":"See that ye refuse not him that speaketh. For if they escaped not who refused him that spake on earth, much more shall not we escape, if we turn away from him that speaketh from heaven:"},{"ref":"Hebrews 12:26","text":"Whose voice then shook the earth: but now he hath promised, saying, Yet once more I shake not the earth only, but also heaven."},{"ref":"Hebrews 12:27","text":"And this word, Yet once more, signifieth the removing of those things that are shaken, as of things that are made, that those things which cannot be shaken may remain."},{"ref":"Hebrews 12:28","text":"Wherefore we receiving a kingdom which cannot be moved, let us have grace, whereby we may serve God acceptably with reverence and godly fear:"}],"WEB":[{"ref":"Hebrews 12:22","text":"But you have come to Mount Zion, and to the city of the living God, the heavenly Jerusalem, and to innumerable multitudes of angels,"},{"ref":"Hebrews 12:23","text":"to the festal gathering and assembly of the firstborn who are enrolled in heaven, to God the Judge of all, to the spirits of just men made perfect,"},{"ref":"Hebrews 12:24","text":"to Jesus, the mediator of a new covenant, and to the blood of sprinkling that speaks better than that of Abel."},{"ref":"Hebrews 12:25","text":"See that you don’t refuse him who speaks. For if they didn’t escape when they refused him who warned on the earth, how much more will we not escape who turn away from him who warns from heaven,"},{"ref":"Hebrews 12:26","text":"whose voice shook the earth then, but now he has promised, saying, “Yet once more I will shake not only the earth, but also the heavens.”"},{"ref":"Hebrews 12:27","text":"This phrase, “Yet once more” signifies the removing of those things that are shaken, as of things that have been made, that those things which are not shaken may remain."},{"ref":"Hebrews 12:28","text":"Therefore, receiving a Kingdom that can’t be shaken, let’s have grace, through which we serve God acceptably, with reverence and awe,"}]},"2-timothy-3-1-5-perilous-times":{"BSB":[{"ref":"2 Timothy 3:1","text":"But understand this: In the last days terrible times will come."},{"ref":"2 Timothy 3:2","text":"For men will be lovers of themselves, lovers of money, boastful, arrogant, abusive, disobedient to their parents, ungrateful, unholy,"},{"ref":"2 Timothy 3:3","text":"unloving, unforgiving, slanderous, without self-control, brutal, without love of good,"},{"ref":"2 Timothy 3:4","text":"traitorous, reckless, conceited, lovers of pleasure rather than lovers of God,"},{"ref":"2 Timothy 3:5","text":"having a form of godliness but denying its power. Turn away from such as these!"}],"KJV":[{"ref":"2 Timothy 3:1","text":"This know also, that in the last days perilous times shall come."},{"ref":"2 Timothy 3:2","text":"For men shall be lovers of their own selves, covetous, boasters, proud, blasphemers, disobedient to parents, unthankful, unholy,"},{"ref":"2 Timothy 3:3","text":"Without natural affection, trucebreakers, false accusers, incontinent, fierce, despisers of those that are good,"},{"ref":"2 Timothy 3:4","text":"Traitors, heady, highminded, lovers of pleasures more than lovers of God;"},{"ref":"2 Timothy 3:5","text":"Having a form of godliness, but denying the power thereof: from such turn away."}],"WEB":[{"ref":"2 Timothy 3:1","text":"But know this: that in the last days, grievous times will come."},{"ref":"2 Timothy 3:2","text":"For men will be lovers of self, lovers of money, boastful, arrogant, blasphemers, disobedient to parents, unthankful, unholy,"},{"ref":"2 Timothy 3:3","text":"without natural affection, unforgiving, slanderers, without self-control, fierce, not lovers of good,"},{"ref":"2 Timothy 3:4","text":"traitors, headstrong, conceited, lovers of pleasure rather than lovers of God,"},{"ref":"2 Timothy 3:5","text":"holding a form of godliness, but having denied its power. Turn away from these, also."}]},"revelation-1-and-22-time-texts":{"BSB":[{"ref":"Revelation 1:1","text":"This is the revelation of Jesus Christ, which God gave Him to show His servants what must soon come to pass. He made it known by sending His angel to His servant John,"},{"ref":"Revelation 1:2","text":"who testifies to everything he saw. This is the word of God and the testimony of Jesus Christ."},{"ref":"Revelation 1:3","text":"Blessed is the one who reads aloud the words of this prophecy, and blessed are those who hear and obey what is written in it, because the time is near."},{"ref":"Revelation 22:6","text":"Then the angel said to me, “These words are faithful and true. The Lord, the God of the spirits of the prophets, has sent His angel to show His servants what must soon take place.”"},{"ref":"Revelation 22:7","text":"“Behold, I am coming soon. Blessed is the one who keeps the words of prophecy in this book.”"},{"ref":"Revelation 22:8","text":"And I am John, who heard and saw these things. And when I had heard and seen them, I fell down to worship at the feet of the angel who had shown me these things."},{"ref":"Revelation 22:9","text":"But he said to me, “Do not do that! I am a fellow servant with you and your brothers the prophets, and with those who keep the words of this book. Worship God!”"},{"ref":"Revelation 22:10","text":"Then he told me, “Do not seal up the words of prophecy in this book, because the time is near."}],"KJV":[{"ref":"Revelation 1:1","text":"The Revelation of Jesus Christ, which God gave unto him, to shew unto his servants things which must shortly come to pass; and he sent and signified it by his angel unto his servant John:"},{"ref":"Revelation 1:2","text":"Who bare record of the word of God, and of the testimony of Jesus Christ, and of all things that he saw."},{"ref":"Revelation 1:3","text":"Blessed is he that readeth, and they that hear the words of this prophecy, and keep those things which are written therein: for the time is at hand."},{"ref":"Revelation 22:6","text":"And he said unto me, These sayings are faithful and true: and the Lord God of the holy prophets sent his angel to shew unto his servants the things which must shortly be done."},{"ref":"Revelation 22:7","text":"Behold, I come quickly: blessed is he that keepeth the sayings of the prophecy of this book."},{"ref":"Revelation 22:8","text":"And I John saw these things, and heard them. And when I had heard and seen, I fell down to worship before the feet of the angel which shewed me these things."},{"ref":"Revelation 22:9","text":"Then saith he unto me, See thou do it not: for I am thy fellowservant, and of thy brethren the prophets, and of them which keep the sayings of this book: worship God."},{"ref":"Revelation 22:10","text":"And he saith unto me, Seal not the sayings of the prophecy of this book: for the time is at hand."}],"WEB":[{"ref":"Revelation 1:1","text":"This is the Revelation of Jesus Christ, which God gave him to show to his servants the things which must happen soon, which he sent and made known by his angel to his servant, John,"},{"ref":"Revelation 1:2","text":"who testified to God’s word and of the testimony of Jesus Christ, about everything that he saw."},{"ref":"Revelation 1:3","text":"Blessed is he who reads and those who hear the words of the prophecy, and keep the things that are written in it, for the time is at hand."},{"ref":"Revelation 22:6","text":"He said to me, “These words are faithful and true. The Lord God of the spirits of the prophets sent his angel to show to his bondservants the things which must happen soon.”"},{"ref":"Revelation 22:7","text":"“Behold, I come quickly. Blessed is he who keeps the words of the prophecy of this book.”"},{"ref":"Revelation 22:8","text":"Now I, John, am the one who heard and saw these things. When I heard and saw, I fell down to worship before the feet of the angel who had shown me these things."},{"ref":"Revelation 22:9","text":"He said to me, “See you don’t do it! I am a fellow bondservant with you and with your brothers, the prophets, and with those who keep the words of this book. Worship God.”"},{"ref":"Revelation 22:10","text":"He said to me, “Don’t seal up the words of the prophecy of this book, for the time is at hand."}]},"revelation-13-beast-666":{"BSB":[{"ref":"Revelation 13:1","text":"Then I saw a beast with ten horns and seven heads rising out of the sea. There were ten royal crowns on its horns and blasphemous names on its heads."},{"ref":"Revelation 13:2","text":"The beast I saw was like a leopard, with the feet of a bear and the mouth of a lion. And the dragon gave the beast his power and his throne and great authority."},{"ref":"Revelation 13:3","text":"One of the heads of the beast appeared to be mortally wounded. But the mortal wound was healed, and the whole world marveled and followed the beast."},{"ref":"Revelation 13:4","text":"They worshiped the dragon who had given authority to the beast, and they worshiped the beast, saying, “Who is like the beast, and who can wage war against it?”"},{"ref":"Revelation 13:5","text":"The beast was given a mouth to speak arrogant and blasphemous words, and authority to act for 42 months."},{"ref":"Revelation 13:6","text":"And the beast opened its mouth to speak blasphemies against God and to slander His name and His tabernacle—those who dwell in heaven."},{"ref":"Revelation 13:7","text":"Then the beast was permitted to wage war against the saints and to conquer them, and it was given authority over every tribe and people and tongue and nation."},{"ref":"Revelation 13:8","text":"And all who dwell on the earth will worship the beast—all whose names have not been written from the foundation of the world in the Book of Life belonging to the Lamb who was slain."},{"ref":"Revelation 13:9","text":"He who has an ear, let him hear:"},{"ref":"Revelation 13:10","text":"“If anyone is destined for captivity, into captivity he will go; if anyone is to die by the sword, by the sword he must be killed.” Here is a call for the perseverance and faith of the saints."},{"ref":"Revelation 13:11","text":"Then I saw another beast rising out of the earth. This beast had two horns like a lamb, but spoke like a dragon."},{"ref":"Revelation 13:12","text":"And this beast exercised all the authority of the first beast and caused the earth and those who dwell in it to worship the first beast, whose mortal wound had been healed."},{"ref":"Revelation 13:13","text":"And the second beast performed great signs to cause even fire from heaven to come down to earth in the presence of the people."},{"ref":"Revelation 13:14","text":"Because of the signs it was given to perform on behalf of the first beast, it deceived those who dwell on the earth, telling them to make an image to the beast that had been wounded by the sword and yet had lived."},{"ref":"Revelation 13:15","text":"The second beast was permitted to give breath to the image of the first beast, so that the image could speak and cause all who refused to worship it to be killed."},{"ref":"Revelation 13:16","text":"And the second beast required all people small and great, rich and poor, free and slave, to receive a mark on their right hand or on their forehead,"},{"ref":"Revelation 13:17","text":"so that no one could buy or sell unless he had the mark—the name of the beast or the number of its name."},{"ref":"Revelation 13:18","text":"Here is a call for wisdom: Let the one who has insight calculate the number of the beast, for it is the number of a man, and that number is 666."}],"KJV":[{"ref":"Revelation 13:1","text":"And I stood upon the sand of the sea, and saw a beast rise up out of the sea, having seven heads and ten horns, and upon his horns ten crowns, and upon his heads the name of blasphemy."},{"ref":"Revelation 13:2","text":"And the beast which I saw was like unto a leopard, and his feet were as the feet of a bear, and his mouth as the mouth of a lion: and the dragon gave him his power, and his seat, and great authority."},{"ref":"Revelation 13:3","text":"And I saw one of his heads as it were wounded to death; and his deadly wound was healed: and all the world wondered after the beast."},{"ref":"Revelation 13:4","text":"And they worshipped the dragon which gave power unto the beast: and they worshipped the beast, saying, Who is like unto the beast? who is able to make war with him?"},{"ref":"Revelation 13:5","text":"And there was given unto him a mouth speaking great things and blasphemies; and power was given unto him to continue forty and two months."},{"ref":"Revelation 13:6","text":"And he opened his mouth in blasphemy against God, to blaspheme his name, and his tabernacle, and them that dwell in heaven."},{"ref":"Revelation 13:7","text":"And it was given unto him to make war with the saints, and to overcome them: and power was given him over all kindreds, and tongues, and nations."},{"ref":"Revelation 13:8","text":"And all that dwell upon the earth shall worship him, whose names are not written in the book of life of the Lamb slain from the foundation of the world."},{"ref":"Revelation 13:9","text":"If any man have an ear, let him hear."},{"ref":"Revelation 13:10","text":"He that leadeth into captivity shall go into captivity: he that killeth with the sword must be killed with the sword. Here is the patience and the faith of the saints."},{"ref":"Revelation 13:11","text":"And I beheld another beast coming up out of the earth; and he had two horns like a lamb, and he spake as a dragon."},{"ref":"Revelation 13:12","text":"And he exerciseth all the power of the first beast before him, and causeth the earth and them which dwell therein to worship the first beast, whose deadly wound was healed."},{"ref":"Revelation 13:13","text":"And he doeth great wonders, so that he maketh fire come down from heaven on the earth in the sight of men,"},{"ref":"Revelation 13:14","text":"And deceiveth them that dwell on the earth by the means of those miracles which he had power to do in the sight of the beast; saying to them that dwell on the earth, that they should make an image to the beast, which had the wound by a sword, and did live."},{"ref":"Revelation 13:15","text":"And he had power to give life unto the image of the beast, that the image of the beast should both speak, and cause that as many as would not worship the image of the beast should be killed."},{"ref":"Revelation 13:16","text":"And he causeth all, both small and great, rich and poor, free and bond, to receive a mark in their right hand, or in their foreheads:"},{"ref":"Revelation 13:17","text":"And that no man might buy or sell, save he that had the mark, or the name of the beast, or the number of his name."},{"ref":"Revelation 13:18","text":"Here is wisdom. Let him that hath understanding count the number of the beast: for it is the number of a man; and his number is Six hundred threescore and six."}],"WEB":[{"ref":"Revelation 13:1","text":"Then I stood on the sand of the sea. I saw a beast coming up out of the sea, having ten horns and seven heads. On his horns were ten crowns, and on his heads, blasphemous names."},{"ref":"Revelation 13:2","text":"The beast which I saw was like a leopard, and his feet were like those of a bear, and his mouth like the mouth of a lion. The dragon gave him his power, his throne, and great authority."},{"ref":"Revelation 13:3","text":"One of his heads looked like it had been wounded fatally. His fatal wound was healed, and the whole earth marveled at the beast."},{"ref":"Revelation 13:4","text":"They worshiped the dragon, because he gave his authority to the beast, and they worshiped the beast, saying, “Who is like the beast? Who is able to make war with him?”"},{"ref":"Revelation 13:5","text":"A mouth speaking great things and blasphemy was given to him. Authority to make war for forty-two months was given to him."},{"ref":"Revelation 13:6","text":"He opened his mouth for blasphemy against God, to blaspheme his name, and his dwelling, those who dwell in heaven."},{"ref":"Revelation 13:7","text":"It was given to him to make war with the saints, and to overcome them. Authority over every tribe, people, language, and nation was given to him."},{"ref":"Revelation 13:8","text":"All who dwell on the earth will worship him, everyone whose name has not been written from the foundation of the world in the book of life of the Lamb who has been killed."},{"ref":"Revelation 13:9","text":"If anyone has an ear, let him hear."},{"ref":"Revelation 13:10","text":"If anyone is to go into captivity, he will go into captivity. If anyone is to be killed with the sword, he must be killed. Here is the endurance and the faith of the saints."},{"ref":"Revelation 13:11","text":"I saw another beast coming up out of the earth. He had two horns like a lamb, and he spoke like a dragon."},{"ref":"Revelation 13:12","text":"He exercises all the authority of the first beast in his presence. He makes the earth and those who dwell in it to worship the first beast, whose fatal wound was healed."},{"ref":"Revelation 13:13","text":"He performs great signs, even making fire come down out of the sky to the earth in the sight of people."},{"ref":"Revelation 13:14","text":"He deceives my own people who dwell on the earth because of the signs he was granted to do in front of the beast, saying to those who dwell on the earth that they should make an image to the beast who had the sword wound and lived."},{"ref":"Revelation 13:15","text":"It was given to him to give breath to it, to the image of the beast, that the image of the beast should both speak, and cause as many as wouldn’t worship the image of the beast to be killed."},{"ref":"Revelation 13:16","text":"He causes all, the small and the great, the rich and the poor, and the free and the slave, to be given marks on their right hands, or on their foreheads;"},{"ref":"Revelation 13:17","text":"and that no one would be able to buy or to sell, unless he has that mark, which is the name of the beast or the number of his name."},{"ref":"Revelation 13:18","text":"Here is wisdom. He who has understanding, let him calculate the number of the beast, for it is the number of a man. His number is six hundred sixty-six."}]},"revelation-17-harlot-seven-kings":{"BSB":[{"ref":"Revelation 17:1","text":"Then one of the seven angels with the seven bowls came and said to me, “Come, I will show you the punishment of the great prostitute, who sits on many waters."},{"ref":"Revelation 17:2","text":"The kings of the earth were immoral with her, and those who dwell on the earth were intoxicated with the wine of her immorality.”"},{"ref":"Revelation 17:3","text":"And the angel carried me away in the Spirit into a wilderness, where I saw a woman sitting on a scarlet beast that was covered with blasphemous names and had seven heads and ten horns."},{"ref":"Revelation 17:4","text":"The woman was dressed in purple and scarlet, and adorned with gold and precious stones and pearls. She held in her hand a golden cup full of abominations and the impurities of her sexual immorality."},{"ref":"Revelation 17:5","text":"And on her forehead a mysterious name was written: BABYLON THE GREAT, THE MOTHER OF PROSTITUTES AND OF THE ABOMINATIONS OF THE EARTH."},{"ref":"Revelation 17:6","text":"I could see that the woman was drunk with the blood of the saints and witnesses for Jesus. And I was utterly amazed at the sight of her."},{"ref":"Revelation 17:7","text":"“Why are you so amazed?” said the angel. “I will tell you the mystery of the woman and of the beast that carries her, which has the seven heads and ten horns."},{"ref":"Revelation 17:8","text":"The beast that you saw—it was, and now is no more, but is about to come up out of the Abyss and go to its destruction. And those who dwell on the earth whose names were not written in the Book of Life from the foundation of the world will marvel when they see the beast that was, and is not, and yet will be."},{"ref":"Revelation 17:9","text":"This calls for a mind with wisdom. The seven heads are seven mountains on which the woman sits."},{"ref":"Revelation 17:10","text":"There are also seven kings. Five have fallen, one is, and the other has not yet come; but when he does come, he must remain for only a little while."},{"ref":"Revelation 17:11","text":"The beast that was, and now is not, is an eighth king, who belongs to the other seven and is going into destruction."},{"ref":"Revelation 17:12","text":"The ten horns you saw are ten kings who have not yet received a kingdom, but will receive one hour of authority as kings, along with the beast."},{"ref":"Revelation 17:13","text":"These kings have one purpose: to yield their power and authority to the beast."},{"ref":"Revelation 17:14","text":"They will make war against the Lamb, and the Lamb will triumph over them, because He is Lord of lords and King of kings; and He will be accompanied by His called and chosen and faithful ones.”"},{"ref":"Revelation 17:15","text":"Then the angel said to me, “The waters you saw, where the prostitute was seated, are peoples and multitudes and nations and tongues."},{"ref":"Revelation 17:16","text":"And the ten horns and the beast that you saw will hate the prostitute. They will leave her desolate and naked, and will eat her flesh and burn her with fire."},{"ref":"Revelation 17:17","text":"For God has put it into their hearts to carry out His purpose by uniting to give their kingdom to the beast, until the words of God are fulfilled."},{"ref":"Revelation 17:18","text":"And the woman you saw is the great city that rules over the kings of the earth.”"}],"KJV":[{"ref":"Revelation 17:1","text":"And there came one of the seven angels which had the seven vials, and talked with me, saying unto me, Come hither; I will shew unto thee the judgment of the great whore that sitteth upon many waters:"},{"ref":"Revelation 17:2","text":"With whom the kings of the earth have committed fornication, and the inhabitants of the earth have been made drunk with the wine of her fornication."},{"ref":"Revelation 17:3","text":"So he carried me away in the spirit into the wilderness: and I saw a woman sit upon a scarlet coloured beast, full of names of blasphemy, having seven heads and ten horns."},{"ref":"Revelation 17:4","text":"And the woman was arrayed in purple and scarlet colour, and decked with gold and precious stones and pearls, having a golden cup in her hand full of abominations and filthiness of her fornication:"},{"ref":"Revelation 17:5","text":"And upon her forehead was a name written, MYSTERY, BABYLON THE GREAT, THE MOTHER OF HARLOTS AND ABOMINATIONS OF THE EARTH."},{"ref":"Revelation 17:6","text":"And I saw the woman drunken with the blood of the saints, and with the blood of the martyrs of Jesus: and when I saw her, I wondered with great admiration."},{"ref":"Revelation 17:7","text":"And the angel said unto me, Wherefore didst thou marvel? I will tell thee the mystery of the woman, and of the beast that carrieth her, which hath the seven heads and ten horns."},{"ref":"Revelation 17:8","text":"The beast that thou sawest was, and is not; and shall ascend out of the bottomless pit, and go into perdition: and they that dwell on the earth shall wonder, whose names were not written in the book of life from the foundation of the world, when they behold the beast that was, and is not, and yet is."},{"ref":"Revelation 17:9","text":"And here is the mind which hath wisdom. The seven heads are seven mountains, on which the woman sitteth."},{"ref":"Revelation 17:10","text":"And there are seven kings: five are fallen, and one is, and the other is not yet come; and when he cometh, he must continue a short space."},{"ref":"Revelation 17:11","text":"And the beast that was, and is not, even he is the eighth, and is of the seven, and goeth into perdition."},{"ref":"Revelation 17:12","text":"And the ten horns which thou sawest are ten kings, which have received no kingdom as yet; but receive power as kings one hour with the beast."},{"ref":"Revelation 17:13","text":"These have one mind, and shall give their power and strength unto the beast."},{"ref":"Revelation 17:14","text":"These shall make war with the Lamb, and the Lamb shall overcome them: for he is Lord of lords, and King of kings: and they that are with him are called, and chosen, and faithful."},{"ref":"Revelation 17:15","text":"And he saith unto me, The waters which thou sawest, where the whore sitteth, are peoples, and multitudes, and nations, and tongues."},{"ref":"Revelation 17:16","text":"And the ten horns which thou sawest upon the beast, these shall hate the whore, and shall make her desolate and naked, and shall eat her flesh, and burn her with fire."},{"ref":"Revelation 17:17","text":"For God hath put in their hearts to fulfil his will, and to agree, and give their kingdom unto the beast, until the words of God shall be fulfilled."},{"ref":"Revelation 17:18","text":"And the woman which thou sawest is that great city, which reigneth over the kings of the earth."}],"WEB":[{"ref":"Revelation 17:1","text":"One of the seven angels who had the seven bowls came and spoke with me, saying, “Come here. I will show you the judgment of the great prostitute who sits on many waters,"},{"ref":"Revelation 17:2","text":"with whom the kings of the earth committed sexual immorality. Those who dwell in the earth were made drunken with the wine of her sexual immorality.”"},{"ref":"Revelation 17:3","text":"He carried me away in the Spirit into a wilderness. I saw a woman sitting on a scarlet-colored beast, full of blasphemous names, having seven heads and ten horns."},{"ref":"Revelation 17:4","text":"The woman was dressed in purple and scarlet, and decked with gold and precious stones and pearls, having in her hand a golden cup full of abominations and the impurities of the sexual immorality of the earth."},{"ref":"Revelation 17:5","text":"And on her forehead a name was written, “MYSTERY, BABYLON THE GREAT, THE MOTHER OF THE PROSTITUTES AND OF THE ABOMINATIONS OF THE EARTH.”"},{"ref":"Revelation 17:6","text":"I saw the woman drunken with the blood of the saints, and with the blood of the martyrs of Jesus. When I saw her, I wondered with great amazement."},{"ref":"Revelation 17:7","text":"The angel said to me, “Why do you wonder? I will tell you the mystery of the woman, and of the beast that carries her, which has the seven heads and the ten horns."},{"ref":"Revelation 17:8","text":"The beast that you saw was, and is not; and is about to come up out of the abyss and to go into destruction. Those who dwell on the earth and whose names have not been written in the book of life from the foundation of the world will marvel when they see that the beast was, and is not, and shall be present."},{"ref":"Revelation 17:9","text":"Here is the mind that has wisdom. The seven heads are seven mountains on which the woman sits."},{"ref":"Revelation 17:10","text":"They are seven kings. Five have fallen, the one is, the other has not yet come. When he comes, he must continue a little while."},{"ref":"Revelation 17:11","text":"The beast that was, and is not, is himself also an eighth, and is of the seven; and he goes to destruction."},{"ref":"Revelation 17:12","text":"The ten horns that you saw are ten kings who have received no kingdom as yet, but they receive authority as kings with the beast for one hour."},{"ref":"Revelation 17:13","text":"These have one mind, and they give their power and authority to the beast."},{"ref":"Revelation 17:14","text":"These will war against the Lamb, and the Lamb will overcome them, for he is Lord of lords, and King of kings, and those who are with him are called chosen and faithful.”"},{"ref":"Revelation 17:15","text":"He said to me, “The waters which you saw, where the prostitute sits, are peoples, multitudes, nations, and languages."},{"ref":"Revelation 17:16","text":"The ten horns which you saw, and the beast, these will hate the prostitute, will make her desolate, will strip her naked, will eat her flesh, and will burn her utterly with fire."},{"ref":"Revelation 17:17","text":"For God has put in their hearts to do what he has in mind, to be of one mind, and to give their kingdom to the beast, until the words of God should be accomplished."},{"ref":"Revelation 17:18","text":"The woman whom you saw is the great city, which reigns over the kings of the earth.”"}]},"revelation-21-22-new-creation":{"BSB":[{"ref":"Revelation 21:1","text":"Then I saw a new heaven and a new earth, for the first heaven and earth had passed away, and the sea was no more."},{"ref":"Revelation 21:2","text":"I saw the holy city, the new Jerusalem, coming down out of heaven from God, prepared as a bride adorned for her husband."},{"ref":"Revelation 21:3","text":"And I heard a loud voice from the throne saying: “Behold, the dwelling place of God is with man, and He will dwell with them. They will be His people, and God Himself will be with them as their God."},{"ref":"Revelation 21:4","text":"‘He will wipe away every tear from their eyes,’ and there will be no more death or mourning or crying or pain, for the former things have passed away.”"},{"ref":"Revelation 21:5","text":"And the One seated on the throne said, “Behold, I make all things new.” Then He said, “Write this down, for these words are faithful and true.”"},{"ref":"Revelation 21:6","text":"And He told me, “It is done! I am the Alpha and the Omega, the Beginning and the End. To the thirsty I will give freely from the spring of the water of life."},{"ref":"Revelation 21:7","text":"The one who overcomes will inherit all things, and I will be his God, and he will be My son."},{"ref":"Revelation 21:8","text":"But to the cowardly and unbelieving and abominable and murderers and sexually immoral and sorcerers and idolaters and all liars, their place will be in the lake that burns with fire and sulfur. This is the second death.”"},{"ref":"Revelation 22:1","text":"Then the angel showed me a river of the water of life, as clear as crystal, flowing from the throne of God and of the Lamb"},{"ref":"Revelation 22:2","text":"down the middle of the main street of the city. On either side of the river stood a tree of life, bearing twelve kinds of fruit and yielding a fresh crop for each month. And the leaves of the tree are for the healing of the nations."},{"ref":"Revelation 22:3","text":"No longer will there be any curse. The throne of God and of the Lamb will be within the city, and His servants will worship Him."},{"ref":"Revelation 22:4","text":"They will see His face, and His name will be on their foreheads."},{"ref":"Revelation 22:5","text":"There will be no more night in the city, and they will have no need for the light of a lamp or of the sun. For the Lord God will shine on them, and they will reign forever and ever."}],"KJV":[{"ref":"Revelation 21:1","text":"And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea."},{"ref":"Revelation 21:2","text":"And I John saw the holy city, new Jerusalem, coming down from God out of heaven, prepared as a bride adorned for her husband."},{"ref":"Revelation 21:3","text":"And I heard a great voice out of heaven saying, Behold, the tabernacle of God is with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, and be their God."},{"ref":"Revelation 21:4","text":"And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."},{"ref":"Revelation 21:5","text":"And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful."},{"ref":"Revelation 21:6","text":"And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely."},{"ref":"Revelation 21:7","text":"He that overcometh shall inherit all things; and I will be his God, and he shall be my son."},{"ref":"Revelation 21:8","text":"But the fearful, and unbelieving, and the abominable, and murderers, and whoremongers, and sorcerers, and idolaters, and all liars, shall have their part in the lake which burneth with fire and brimstone: which is the second death."},{"ref":"Revelation 22:1","text":"And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb."},{"ref":"Revelation 22:2","text":"In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations."},{"ref":"Revelation 22:3","text":"And there shall be no more curse: but the throne of God and of the Lamb shall be in it; and his servants shall serve him:"},{"ref":"Revelation 22:4","text":"And they shall see his face; and his name shall be in their foreheads."},{"ref":"Revelation 22:5","text":"And there shall be no night there; and they need no candle, neither light of the sun; for the Lord God giveth them light: and they shall reign for ever and ever."}],"WEB":[{"ref":"Revelation 21:1","text":"I saw a new heaven and a new earth: for the first heaven and the first earth have passed away, and the sea is no more."},{"ref":"Revelation 21:2","text":"I saw the holy city, New Jerusalem, coming down out of heaven from God, prepared like a bride adorned for her husband."},{"ref":"Revelation 21:3","text":"I heard a loud voice out of heaven saying, “Behold, God’s dwelling is with people, and he will dwell with them, and they will be his people, and God himself will be with them as their God."},{"ref":"Revelation 21:4","text":"He will wipe away every tear from their eyes. Death will be no more; neither will there be mourning, nor crying, nor pain, any more. The first things have passed away.”"},{"ref":"Revelation 21:5","text":"He who sits on the throne said, “Behold, I am making all things new.” He said, “Write, for these words of God are faithful and true.”"},{"ref":"Revelation 21:6","text":"He said to me, “I have become the Alpha and the Omega, the Beginning and the End. I will give freely to him who is thirsty from the spring of the water of life."},{"ref":"Revelation 21:7","text":"He who overcomes, I will give him these things. I will be his God, and he will be my son."},{"ref":"Revelation 21:8","text":"But for the cowardly, unbelieving, sinners, abominable, murderers, sexually immoral, sorcerers, idolaters, and all liars, their part is in the lake that burns with fire and sulfur, which is the second death.”"},{"ref":"Revelation 22:1","text":"He showed me a river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb,"},{"ref":"Revelation 22:2","text":"in the middle of its street. On this side of the river and on that was the tree of life, bearing twelve kinds of fruits, yielding its fruit every month. The leaves of the tree were for the healing of the nations."},{"ref":"Revelation 22:3","text":"There will be no curse any more. The throne of God and of the Lamb will be in it, and his servants will serve him."},{"ref":"Revelation 22:4","text":"They will see his face, and his name will be on their foreheads."},{"ref":"Revelation 22:5","text":"There will be no night, and they need no lamp light or sun light; for the Lord God will illuminate them. They will reign forever and ever."}]}}`),a={translations:e,passages:t};export{a as default,t as passages,e as translations};
